window.__LEX={"G4400":"<h1>procheirizomai</h1>\n<p>Strong n° 4400 <i>Prononciation [prokh-i-rid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>remettre dans les mains</li>\n<li>prendre dans les mains</li>\n<li>déterminer</li>\n<li>choisir, désigner, nommer\n<ol type=\"a\">\n<li>pour un usage</li>\n<li>pour le salut</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προχειρίζω</b> <span>(<i>f. att</i>. -ιῶ)</span><br><b>      1</b> remettre entre les mains de, livrer : τινά, DIN. <i>110, 8,</i> qqn (un condamné) ;<br><b>      2</b> avoir sous la main, à sa portée, tout prêt, <i>acc</i>. POL. <i>3, 107, 10 ; au pass</i>. προκεχειρισμένος, η, ον, qui est tout prêt, PLAT. <i>Leg. 643</i> a ; <i>joint à</i> ἕτοιμος, DÉM. <i>85, 7 ; avec un dat</i>. tout prêt pour, destiné à, POL. <i>3, 40, 14 ;</i><br><b>      3</b> élire auparavant, <i>au pass</i>. POL. <i>3, 106, 2 ;</i><br><b><i>Moy</i>. προχειρίζομαι</b> <span>(<i>f. att</i>. -ιοῦμαι)</span> : manier auparavant, <i>d’où :</i><br><b>      1</b> prendre en main, se charger de, <i>acc</i>. AR. <i>Eccl. 729 ;</i><br><b>      2</b> <i>p. suite,</i> préparer pour soi (une armée, une flotte, <i>etc.) acc</i>. DÉM. <i>45, 10 ;</i> POL. <i>1, 16, 2, etc. ;</i> LUC. <i>M. cond. 14, etc. ;</i><br><b>      3</b> traiter auparavant, commencer l’examen d’une question, ARSTT. <i>Categ. 8, 31, etc. ;</i><br><b>      4</b> élire d’avance à main levée, désigner d’avance, choisir auparavant : τινα ἐπί τι, DÉM. <i>773, 18 ;</i> ἐπί τινι, PLUT. <i>Cæs. 58,</i> qqn en vue de qqe ch. ; τί τινι, POL. <i>3, 40, 14,</i> assigner qqe ch. à qqn ; <i>p. suite,</i> décider de, <i>inf</i>. POL. <i>3, 40, 2</i>.<br><span><b>Étym</b>. π. χείρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προχειριζομαι - προχειρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4401":"<h1>procheirotoneo</h1>\n<p>Strong n° 4401 <i>Prononciation [prokh-i-rot-on-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>choisir ou désigner d'avance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·χειροτονέω-ῶ :<br>      1</b> élire auparavant à main levée, <i>d’où</i> élire auparavant, <i>en gén</i>. PLAT. <i>Leg. 765 b et c ;</i> ESCHN. <i>4, 11 ;</i> NT. <i>Ap. 10, 41 ;</i> DC. <i>50, 4 ;</i><br><b>      2</b> voter préalablement, voter sur la prise en considération (d’une proposition) DÉM. <i>703, 18</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προχειροτονεω - προχειροτονέω</font></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4402":"<h1>Prochoros</h1>\n<p>Strong n° 4402 <i>Prononciation [prokh'-or-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Prochore (Angl. Prochorus) = « qui dirige le chœur »\n<ol><li>un des sept diacres choisis par l'église à Jérusalem</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>προ·χορεύω</b>, conduire un chœur, EUR. <i>Ph. 797</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Προχορος - Πρόχορος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4403":"<h1>prumna</h1>\n<p>Strong n° 4403 <i>Prononciation [proom'-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la poupe ou partie arrière d'un navire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρύμνα, ης (ἡ)</b> <span>[ᾰ]</span> <i>litt. adj. f</i>. qui est à l’extrémité inférieure, à l’arrière : ναῦς πρύμνη, IL. <i>7, 383 ; 10, 35, etc. ;</i> OD. <i>2, 417, etc</i>. partie du navire qui est à l’arrière, poupe ; <i>au plur</i>. πρύμναι νῆες, IL. <i>12, 403 ; 13, 333, etc. m. sign. ; subst</i>. πρύμνη νηός, OD. <i>13, 84,</i> poupe d’un navire ; κατὰ πρύμναν, SOPH. <i>Ph. 1451,</i> par derrière, en poupe ; <i>d’où</i> avec vent arrière, THC. <i>2, 97 ; fig</i>. πρύμνα πόλεος, la poupe de la ville, <i>càd</i>. l’Acropole, ESCHL. <i>Suppl. 344 ; ou en gén</i>. le vaisseau de l’État, ESCHL. <i>Sept. 2 et 760 ; p. ext</i>. partie inférieure, pied d’une montagne, EUR. <i>El. 443</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πρύμνη, HOM. <i>ll. cc., et att. par nécess. métr. c</i>. τόλμη <i>p</i>. τόλμα, SOPH. <i>Ph. 482 ;</i> AR. <i>Vesp. 399</i>.<br><span><b>Étym</b>. πρυμνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρυμνα - πρύμνα</font>\n<br><br>vient de prumnus (dernier)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4404":"<h1>proi</h1>\n<p>Strong n° 4404 <i>Prononciation [pro-ee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dès le matin, de bonne heure, tôt, à l'aube</li>\n<li>la quatrième veille de la nuit, qui va approximativement de 3 à 6 heures</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωΐ</b> <span>[ῐ]</span> <i>p. contr. att</i>. <b>πρῴ</b>, <i>adv. :</i><br><b>   I</b> le matin, dès le matin, IL. <i>8, 530 ; 18, 277, 303 ;</i> ATT. ; <i>avec le gén</i>. πρωῒ τῆς ἡμέρης, HDT. <i>9, 101 ;</i> ἡμέρας τὸ πρῴ, XÉN. <i>Hell. 1, 1, 30,</i> au point du jour ; πρῲ τῇ ὑστεραίᾳ, XÉN. <i>Cyr. 1, 4, 16,</i> le lendemain de bonne heure ; ἅμα πρωΐ, NT. <i>Matth. 20, 1,</i> au point du jour ; ἀπὸ πρωῒ ἕως ἑσπέρας, NT. <i>Ap. 28, 23,</i> du matin jusqu’au soir ;<br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> de bonne heure, HÉS. <i>O. 463, etc. ;</i> AR. <i>Av. 132, etc. ; avec le gén</i>. πρ. τοῦ θέρεος, HPC. <i>939</i> e, dès le commencement de l’été ; πρῲ τῆς ὥρας, THC. <i>7, 39,</i> au commencement de la saison ;<br><b>      2</b> trop tôt, avant le temps, ESCHL. <i>Pr. 696 ;</i> SOPH. <i>Tr. 631 ;</i> THC. <i>4, 6 ;</i> PLAT. <i>Parm. 135</i> c, <i>etc</i>.<br><span>•<i> Cp</i>. πρωΐτερον, HPC. <i>ou</i> πρωϊαίτερον, XÉN. <i>An. 3, 4, 1 ;</i> PLAT. <i>Theæt. 130</i> e, <i>etc. ; p. contr</i>. πρῳαίτερον, THC. <i>7, 39</i>. <i>• Sup</i>. πρωΐτατα, THC. <i>7, 19 ; ou</i> πρωϊαίτατα, PLAT. <i>Prot. 326</i> c.<br><span><b>Étym</b>. πρό.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωι - πρωΐ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (6)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4405":"<h1>proia</h1>\n<p>Strong n° 4405 <i>Prononciation [pro-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tôt dans la matinée, appartenant au matin, le début de la journée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωΐα, ας (ἡ)</b> <i>v</i>. πρώϊος.<br><br>\n<b>πρώϊος, α, ον :<br>      1</b> du matin, de bon matin, matinal, HDT. <i>8, 6 ;</i> ANTH. <i>6, 304, etc. ; adv</i>. πρώϊον, IL. <i>15, 470,</i> le matin, de bonne heure ; <i>subst</i>. ἡ πρωΐα, NT. <i>Joh. 18, 28 ; Matth. 27, 1,</i> l’heure matinale, le matin ; <i>adv</i>., πρωΐας, NT. <i>Matth. 21, 18,</i> le matin ; καθ᾽ ἑκάστην πρωΐαν, JOS. <i>A.J. 7, 8, 1,</i> chaque matin ;<br><b>      2</b> de bonne heure, <i>en gén</i>. HDT. <i>8, 130 ; en parl. de fruits,</i> précoce, AR. <i>Vesp. 264, Pax 1001, etc. ; en parl. d’œufs, p. opp. à</i> κύψιος, ARSTT. <i>H.A. 5, 9, 6 ; en parl. de lieux où les fruits sont précoces,</i> TH. <i>H.P. 8, 2, 9, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Att</i>. πρῷος, AR. <i>Vesp. 264</i>.<br><span><b>Étym</b>. πρωΐ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωια - πρωΐα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G4406":"<h1>proimos</h1>\n<p>Strong n° 4406 <i>Prononciation [pro'-ee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>premier, tôt\n<ol type=\"a\">\n<li>de la première pluie qui arrive en Octobre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>πρώϊμος, ος, ον</b> <span>[ῐ]</span> qui vient de bonne heure, précoce, XÉN. <i>Œc. 17, 4 ;</i> ARSTT. <i>Probl. 20, 14, 2 ;</i> GEOP. <i>2, 14, 1 ;</i> πρώϊμον ἔτος, GEOP. <i>11, 18, 5,</i> année précoce, <i>càd</i>. où les fruits sont précoces ; <i>fig. en parl. de méchanceté,</i> MÉTROD. (STOB. <i>Fl. 52, 7</i>).<br><span>•<i> Cp</i>. -ώτερος, GEOP.<br><span><b>Étym</b>. πρωΐ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωιμος - πρόϊμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4407":"<h1>proinos</h1>\n<p>Strong n° 4407 <i>Prononciation [pro-ee-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>qui appartient au matin, matinal</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωϊνός, ή, όν</b> <span>[ῐ]</span> du matin, matinal, SPT. <i>Gen. 49, 27, etc. ;</i> PLUT. <i>M. 726</i> e ; BABR. <i>97, 17 ;</i> ATH. <i>11</i> c, <i>etc. ; subst</i>. τὸ πρωϊνόν, SPT. <i>1Esdr. 5, 50,</i> le matin.<br><span><b>Étym</b>. πρωΐ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωινος - πρωϊνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4408":"<h1>prora</h1>\n<p>Strong n° 4408 <i>Prononciation [pro'-ra]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la proue ou partie avant d'un navire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρῴρα</b> <i>ou mieux</i> <b>πρῷρα, ας (ἡ) :<br>      1</b> proue, partie antérieure d’un navire, OD. <i>12, 230 ;</i> ESCHL. <i>Sept. 208 ;</i> SOPH. <i>Ph. 482 ;</i> πνεῦμα τοὐκ πρῴρας, SOPH. <i>Ph. 639,</i> vent qui vient de la proue, <i>càd</i>. vent contraire, <i>p. opp. à</i> κατὰ πρύμναν ; <i>fig</i>. πρῷρα βιότου, EUR. <i>Tr. 103, litt</i>. la proue du vaisseau de la vie, <i>càd</i>. la première jeunesse ;<br><b>      2</b> <i>p. anal</i>. visage, ESCHL. <i>Ch. 390 ; ou</i> extrémité saillante, pointe, TH. <i>H.P. 2, 1, 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. πρῴρα, <i>v. Meisterh. p. 51, 8. Épq. et ion</i>. πρῴρη, OD. <i>l. c</i>.<br><span><b>Étym</b>. <i>fém. d’un masc</i>. *πρῶρος <i>de</i> *πρόερος, <i>cp. de</i> πρό.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωρα - πρῷρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4409":"<h1>proteuo</h1>\n<p>Strong n° 4409 <i>Prononciation [prote-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être le premier, tenir la première place</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωτεύω</b>, être le premier, tenir le premier rang, PLAT. <i>Leg. 692</i> d ; ISOCR. <i>95</i> d, <i>etc. ;</i> ἐν τοῖς Ἕλλησι, ISOCR. <i>164</i> b, parmi les Grecs ; τινί, XÉN. <i>Ages. 10, 1 ;</i> IS. <i>37, 25, etc. ; ou</i> ἔν τινι, XÉN. <i>Cyr. 8, 4, 5,</i> en qqe ch. ; φιλίᾳ παρά τινι, XÉN. <i>Cyr. 8, 2, 28,</i> occuper la première place dans l’amitié de qqn ; <i>avec un gén. de pers. :</i> τινός, XÉN. <i>Ages. 1, 3 ;</i> ISOCR. <i>141</i> b ; ESCHN. <i>24, 27,</i> l’emporter sur qqn ; τινός τινι, DS. <i>4, 81 ; ou</i> τινὸς περί τι, ESCHN. <i>49, 29,</i> l’emporter sur qqn en qqe ch.<br><span><b>Étym</b>. πρῶτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτευω - πρωτεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4410":"<h1>protokathedria</h1>\n<p>Strong n° 4410 <i>Prononciation [pro-tok-ath-ed-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>s'asseoir dans le premier siège, le siège principal, la place d'honneur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωτο·καθεδρία, ας (ἡ)</b> première place dans une assemblée, préséance, NT. <i>Matth. 23, 6 ;</i> CLÉM. <i>113, 16 Sylb</i>.<br><span><b>Étym</b>. πρ. καθέδρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτοκαθεδρια - πρωτοκαθεδρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4411":"<h1>protoklisia</h1>\n<p>Strong n° 4411 <i>Prononciation [pro-tok-lis-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la première place de repos, la place principale à table</li>\n<li>le rang relatif entre plusieurs places à table variait selon les coutumes des Perses, des Grecs, des Romains ; la disposition que les Juifs avaient choisie du temps de Christ ne peut être déterminée avec précision</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωτο·κλισία, ας (ἡ)</b> <span>[λῐ]</span> la place d’honneur (<i>litt</i>. le premier lit) dans un repas, NT. <i>Matth. 23, 6 ;</i> CLÉM. <i>322, 48 Sylb</i>.<br><span><b>Étym</b>. πρ. κλίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτοκλισια - πρωτοκλισία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4412":"<h1>proton</h1>\n<p>Strong n° 4412 <i>Prononciation [pro'-ton]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>premier en temps ou lieu\n<ol type=\"a\">\n<li>dans toute succession de choses ou personnes</li>\n</ol>\n</li>\n<li>premier dans le rang\n<ol type=\"a\">\n<li>influence, honneur</li>\n<li>chef</li>\n<li>principal</li>\n</ol>\n</li>\n<li>d'abord, auparavant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρῶτον</b> v. <b>, </b>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτον - πρῶτον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n60 fois dans 60 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (7)</li>\n<li>Luc (10)</li>\n<li>Jean (6)</li>\n<li>Actes (6)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G4413":"<h1>protos</h1>\n<p>Strong n° 4413 <i>Prononciation [pro'-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>premier en temps ou lieu\n<ol type=\"a\">\n<li>dans toute succession de choses ou de personnes</li>\n</ol>\n</li>\n<li>premier dans le rang\n<ol type=\"a\">\n<li>influence, honneur</li>\n<li>chef</li>\n<li>principal</li>\n</ol>\n</li>\n<li>d'abord, auparavant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρῶτος, η, ον</b>, premier :<br><b>   I</b> <i>adj. :</i><br><b>      1</b> (<i>dans l’espace</i>) le plus en avant : πρώτοισιν ἐνὶ προμάχοισι, OD. <i>18, 379,</i> parmi les combattants les plus en avant, <i>càd</i>. dans la première ligne de bataille ; πρώτῃ ἐν ὑσμίνῃ, IL. <i>15, 340 ; 20, 395,</i> dans le premier engagement, celui qui se fait en tête de l’ordre de bataille ; ἐνὶ πρώτῳ ὁμάδῳ, IL. <i>17, 380,</i> dans la mêlée la plus en avant ; ἡ πρώτη (<i>s.-e</i>. τάξις) EL. <i>N.A. 2, 6,</i> le premier rang, la première ligne ; τῆς πρώτης τάττειν, ISOCR. <i>271</i> a ; LYS. <i>147, 11,</i> mettre au premier rang, en première ligne ; ἐν πρώτῳ ῥυμῷ, IL. <i>6, 40 ; 16, 371,</i> dans la première partie du timon ; πρῶται θύραι, IL. <i>22, 66,</i> la porte la plus extérieure ; πρῶτον ξύλον, AR. <i>Ach. 28,</i> les bancs de devant dans la Pnyx, au théâtre ;<br><b>      2</b> (<i>avec idée de rang et de nombre</i>) le premier, <i>p. opp. à</i> τῷ δευτέρῳ…, τῷ τριτάτῳ…, τῷ δὲ τετάρτῳ…, πέμπτῳ δέ, IL. <i>23, 265 ; à</i> ὕστατος, IL. <i>5, 703 ;</i> OD. <i>9, 448 ; à</i> τελευταῖος, ESCHL. <i>Ag. 314 ; à</i> μέσον καὶ τελευταῖον, PLUT. <i>M. 5</i> d ; πρῶτος μετά τινα, IL. <i>8, 289,</i> le premier après qqn ; <i>avec le gén. :</i> πρῶτοι πάντων ἀνθρώπων, HDT. <i>2, 2,</i> les premiers de tous les hommes ; τῇ πρώτῃ τῶν ἡμερέων, HDT. <i>7, 168,</i> dès le premier jour ; τὸν πρῶτον τοῦ χρόνου, XÉN. <i>Lac. 1, 5,</i> dans le premier temps, au début ; πρὸς πρώτην ἕω, SOPH. <i>O.C. 477,</i> (tourné) du côté de l’orient ; ἱερὰ καλὰ ἦν εὐθὺς ἐπὶ τοῦ πρώτου (<i>s.-e</i>. ἱερείου) XÉN. <i>An. 4, 3, 9,</i> le sacrifice fut favorable dès la première victime ; ἐν πρώτοις, parmi les premiers, <i>càd</i>. tout d’abord, en premier lieu, IS. <i>67, 29 et 33 ;</i> LUC. <i>Par. 49, etc. ; d’où comme le lat</i>. imprimis, surtout, avant tout, PLAT. <i>Rsp. 522</i> c ; πρῶτος ἀριθμός, EUCL. <i>Elem. 7, 13,</i> nombre premier, qui ne se divise par aucun facteur, <i>p. opp. à</i> σύνθετος ; πρῶτοι πρὸς ἀλλήλους ἀριθμοί, EUCL. <i>Elem. 7, 13,</i> nombres premiers entre eux, nombres qui en dehors de l’unité n’ont pas de diviseur commun ; <i>qqf. au sens de</i> πρότερος, IL. <i>13, 502 ; 18, 92 ;</i> HDT. <i>2, 2 ; 9, 27 ;</i> Ps.-ERATOSTH. <i>Cat. 42, p. 122, etc. ; fig</i>. le plus excellent, le plus distingué, le principal : μετὰ πρώτοισιν ἐών, IL. <i>4, 341,</i> étant parmi les premiers ; οἱ δοκοῦντες πρῶτοι εἶναι, XÉN. <i>Lac. 14, 4,</i> ceux qui passent pour être les premiers ; <i>cf</i>. THC. <i>6, 28 ;</i> XÉN. <i>An. 2, 6, 26 ;</i> αἱ πρῶται πόλεις, THC. <i>2, 8 ; 4, 95,</i> les cités les plus importantes ; <i>joint à</i> ἄριστος, PLAT. <i>Pol. 303</i> b, <i>Leg. 626</i> e ; <i>avec un gén. :</i> οἱ πρῶτοι στρατοῦ, SOPH. <i>Ph. 1305,</i> les premiers de l’armée, les chefs ; <i>cf</i>. EUR. <i>Hec. 304, etc. ; avec un rég. :</i> νόον ἐν πρώτοισι Μυκηναίων ἐτέτυκτο, IL. <i>15, 643,</i> il se trouvait parmi les premiers des Mycéniens pour l’intelligence ; πρῶτος ἀρετῇ, SOPH. <i>Ph. 1425,</i> le premier par le mérite ; πρ. χρήμασι καὶ γένει, THC. <i>3, 65,</i> le premier par la fortune et la naissance ; <i>en mauv. part :</i> μοῖρα πρώτη, SOPH. <i>O.C. 143,</i> le premier lot, <i>càd</i>. la plus grande infortune ;<br><b>   II</b> <i>subst. :</i><br><b>      1</b> τὸ πρῶτον, τὰ πρῶτα, le commencement : τὸ πρῶτον τοῦ ᾄσματος, PLAT. <i>Prot. 343</i> c, le commencement du chant ; τὰ πρῶτα τῆς Ἰλιάδος, PLAT. <i>Rsp. 392</i> c, le commencement de l’Iliade ;<br><b>      2</b> τὰ πρῶτα (<i>s.-e</i>. ἆθλα) le premier prix, SOPH. <i>Aj. 1300, O.C. 1313, etc. ;</i> τὰ πρῶτα λαμϐάνειν, IL. <i>23, 275 ;</i> φέρεσθαι, DC. <i>42, 57 ; 44, 4 ;</i> φέρειν, ANTH. <i>8, 111,</i> remporter le prix ;<br><b>      3</b> τὰ πρῶτα, le plus haut degré, le point le plus élevé ; τὰ πρῶτα τῆς εὐδαιμονίας, LUC. <i>Charid. 10,</i> le comble du bonheur ; φρενῶν ἐς τὰ ἐμεωυτοῦ πρῶτα οὔκω ἀνήκω, HDT. <i>7, 13, litt</i>. je ne suis pas encore arrivé au point culminant de mon esprit, <i>càd</i>. je ne suis pas encore arrivé à toute la prudence (que j’aurai plus tard), je suis encore jeune ; <i>en parl. de pers</i>. les premiers, les plus grands : τῆς γῆς τὰ πρῶτ(α), EUR. <i>Med. 917,</i> les premiers du pays ; τὰ πρῶτα τῶν Ἐρετριέων, HDT. <i>6, 100,</i> les premiers des Érétriens ; τὰ πρ. τῆς βουλῆς, DC. <i>36, 13,</i> les premiers du sénat ; <i>en parl. d’une seule pers</i>. ὁ μηχανικῶν ὢν τὰ πρῶτα, LUC. <i>Hipp. 3,</i> le plus industrieux des artisans ;<br><b>      4</b> <i>t. de philosophie :</i> τὰ πρῶτα, les premiers éléments des choses, les éléments, PLAT. ARSTT. <i>etc. ;</i><br><b>   III</b> <i>adv. :</i><br><b>      1</b> <i>fém</i>. πρώτη : τὴν πρώτην, la première fois, tout d’abord, en premier lieu, au début, HDT. <i>1, 153 ; 3, 134 ;</i> XÉN. <i>Mem. 3, 6, 10 ;</i> DÉM. <i>29, 1, etc. ;</i> τήν γε πρώτην, EL. <i>N.A. 11, 10 ;</i> LUC. <i>Pisc. 39, etc. m. sign. ; avec une prép. :</i> ἀπὸ πρώτης, au commencement, de prime abord, au début, PLAT. <i>Pol. 292</i> b ; κατὰ πρώτας εὐθύς, DC. <i>52, 19 ; et</i> κατὰ τὴν πρώτην εὐθύς, DC. <i>62, 3, m. sign. ;</i> παρὰ πρώτην, PHILSTR. <i>V. Ap. 1, 22,</i> la première fois ;<br><b>      2</b> <i>neutre</i> πρῶτον, πρῶτα <i>et</i> τὸ πρῶτον, τὰ πρῶτα, <i>écrit aussi</i> τοπρῶτον, ταπρῶτα : πρῶτον, d’abord, premièrement : πρῶτόν τε καὶ ὕστατον, HÉS. <i>Th. 34,</i> en premier et en dernier lieu ; πρῶτον μέν, <i>p. opp. à</i> δεύτερον αὖ…, τὸ τρίτον αὖ, IL. <i>6, 179 ;</i> δεύτερον δέ, XÉN. <i>Œc. 4, 15 ; à</i> ἔπειτα…, τὸ τρίτον, PLAT. <i>Leg. 669</i> a ; <i>à</i> ἔπειτα δεύτερον…, ἔπειτα τρίτον, ESCHN. <i>1, 34 ; d’ord</i>. πρῶτον μὲν…, ἔπειτα, ATT. d’abord…, ensuite ; πρ. μὲν…, ἔπειτα…, ἔπειτα, PLAT. <i>Phæd. 89</i> a, d’abord…, ensuite…, ensuite ; πρῶτον μὲν…, ἔπειτα δέ, SOPH. <i>O.C. 632, etc. ;</i> XÉN. <i>Cyr. 2, 1, 2, etc. ;</i> d’abord…, ensuite ; πρῶτον μὲν…, εἶτα, XÉN. <i>An. 1, 3, 2, etc. ; ou</i> εἶτα δέ, XÉN. <i>An. 1, 2, 16 ;</i> πρῶτον μὲν…, αὖ, PLAT. <i>Leg. 935</i> a, <i>m. sign. etc. ; simpl. en corrélat. avec</i> δέ : πρῶτον μὲν…, δέ, XÉN. <i>Cyr. 6, 4, 18, etc. ;</i> PLAT. <i>Phæd. 113</i> b, <i>etc. ; ou sans corrélatif,</i> ESCHL. <i>Ag. 810 ;</i> XÉN. <i>Cyr. 1, 2, 13 ;</i> PLAT. <i>Leg. 933</i> b, <i>etc. ;</i> la première fois, <i>c</i>. πρότερον, EL. <i>N.A. 3, 14 ;</i> πρῶτον ἤ, avant que, ANTH. <i>12, 206 ;</i> EL. <i>V.H. 5, 18 ;</i> — πρῶτα, d’abord, <i>comme</i> πρῶτον, ATT. ; πρῶτα μὲν…, <i>en corrél. avec</i> ἔπειτα, SOPH. <i>Tr. 616 ;</i> XÉN. <i>Hell. 4, 1, 31, etc. ; avec</i> ἔπειτα δέ, SOPH. <i>Ph. 919 ;</i> XÉN. <i>Hell. 7, 1, 7 ; avec</i> εἶτα, SOPH. <i>El. 261 ; avec</i> δέ, ESCHL. <i>Pr. 447 ;</i> SOPH. <i>Tr. 763 ;</i> trop tôt, OD. <i>24, 28 ;</i> — τὸ πρῶτον, tout d’abord, premièrement, au commencement, la première fois, IL. <i>4, 267 ; 23, 324 ;</i> OD. <i>23, 214 ;</i> ESCHL. <i>Ag. 1287 ;</i> SOPH. <i>O.C. 467 ;</i> XÉN. <i>Cyr. 8, 3, 1, etc. ;</i> — τὰ πρῶτα, <i>m. sign</i>. IL. <i>1, 6 ; 17, 612 ;</i> OD. <i>1, 257, etc. ;</i> XÉN. <i>Œc. 7, 4 ; en corrélat. avec</i> αὐτὰρ ἔπειτα, IL. <i>4, 424 ; avec</i> δέ, ESCHL. <i>Pers. 412, etc. ;</i> πρῶτον, πρῶτα, τὸ πρῶτον, τὰ πρῶτα <i>peuvent être précédés de particules de temps au sens du lat</i>. primum, <i>dans</i> ubi primum : ἐπεὶ πρῶτον, OD. <i>13, 133 ;</i> ἐπεὶ πρῶτα, OD. <i>13, 228 ; 17, 573 ;</i> ἐπεὶ τὸ πρῶτον, OD. <i>14, 467 ;</i> ἐπεὶ τὰ πρῶτα, IL. <i>12, 420,</i> aussitôt que, dès que ; <i>de même :</i> ἐπὴν τὰ πρῶτα, IL. <i>6, 489 ;</i> OD. <i>8, 553 ;</i> ἐπειδὴ πρῶτα, IL. <i>19, 9 ;</i> OD. <i>3, 183 ;</i> ὁππότε κε πρῶτον, OD. <i>11, 106 ; 12, 158 ;</i> εὖτ' ἂν πρῶτον, HÉS. <i>O. 600 ;</i> ὡς τὸ πρῶτον, XÉN. <i>An. 7, 8, 14 ;</i> ὅτε πρῶτον, DÉM. <i>274, 30 ;</i> ὅταν πρῶτον, PLAT. <i>Lys. 211</i> b, <i>etc. ; ou construits avec un pronom relatif :</i> ὅντινα πρῶτον, OD. <i>3, 320,</i> celui que seulement une fois.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. πρᾶτος, THCR. <i>Idyl. 18, 56</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *prh₃-to-, premier ; <i>cf. sscr</i>. pū́r-va-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτος - πρῶτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n98 fois dans 92 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (17)</li>\n<li>Marc (10)</li>\n<li>Luc (10)</li>\n<li>Jean (8)</li>\n<li>Actes (11)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (4)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (9)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (18)</li>\n</ul>\n</td></tr>\n</table>","G4414":"<h1>protostates</h1>\n<p>Strong n° 4414 <i>Prononciation [pro-tos-tat'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>quelqu'un qui se tient au premier rang\n<ol type=\"a\">\n<li>un meneur, un chef, un champion, un chef de file, leader, protagoniste</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωτο·στάτης, ου (ὁ)</b> <span>[ᾰ]</span> celui qui se tient en avant <i>après le</i> λοχαγός <i>et l’</i>ἐπιστάτης, chef de file, THC. <i>5, 71 ;</i> EL. TACT. <i>5, 1, 4 ; au plur</i>. soldats du premier rang, XÉN. <i>Cyr. 3, 3, 57 ; fig</i>. chef de parti, NT. <i>Ap. 24, 5</i>.<br><span><b>Étym</b>. πρ. ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτοστατης - πρωτοστάτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4415":"<h1>prototokia</h1>\n<p>Strong n° 4415 <i>Prononciation [pro-tot-ok'-ee-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le droit ou les avantages ou privilèges du fils premier né, primogéniture</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωτοτοκία, ας (ἡ)</b> <i>c</i>. πρωτοτόκια AQU. <i>Gen. 25, 34</i>.<br><br>\n<b>πρωτοτόκια, ων (τὰ)</b> <i>var. c</i>. πρωτοτοκεῖα.<br><br>\n<b>πρωτοτοκεῖα, ων (τὰ)</b> droit d’aînesse, SPT. <i>Gen. 25, 32 ;</i> NT. <i>Hebr. 12, 16</i>.<br><span><b>Étym</b>. πρωτοτοκεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτοτοκια - πρωτοτόκια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4416":"<h1>prototokos</h1>\n<p>Strong n° 4416 <i>Prononciation [pro-tot-ok'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le premier-né\n<ol type=\"a\">\n<li>d'un homme ou d'un animal</li>\n<li>de Christ, le premier né de toute la création</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρωτο·τόκος, ος, ον :<br>      1</b> qui enfante pour la première fois, PLAT. <i>Theæt. 151</i> c, <i>161</i> a ; ANTH. <i>8, 163 ;</i> ORPH. <i>Lith. 191 ;</i><br><b>      2</b> qui met bas pour la première fois, IL. <i>17, 5 ;</i> THCR. <i>Idyl. 5, 27 ;</i> ARSTT. <i>H.A. 5, 14, 20, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. πρατοτόκος <span>[ᾱ]</span> THCR. <i>Idyl. l. c</i>.<br><span><b>Étym</b>. πρ. τίκτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρωτοτοκος - πρωτότοκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Colossiens (2)</li>\n<li>Hébreux (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4417":"<h1>ptaio</h1>\n<p>Strong n° 4417 <i>Prononciation [ptah'-yo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire que quelqu'un trébuche ou tombe</li>\n<li>trébucher, broncher\n<ol type=\"a\">\n<li>errer, faire une erreur, pécher</li>\n<li>tomber dans la misère, devenir misérable</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πταίω</b> <span>(<i>f</i>. πταίσω, <i>ao</i>. ἔπταισα, <i>pf</i>. ἔπταικα ; <i>pass. ao</i>. ἐπταίσθην, <i>pf</i>. ἔπταισμαι)</span><br><b>   I <i>tr</i>.<br>      1</b> heurter <i>ou</i> choquer contre : τι ποτί τινι, PD. <i>fr. 221,</i> une ch. contre une autre ;<br><b>      2</b> <i>p. suite,</i> faire broncher, renverser : τινὰ τῆς ἐλπίδος, HDN <i>8, 5, 1, litt</i>. précipiter qqn d’une espérance ; <i>au pass</i>. τὰ πταισθέντα, LUC. <i>Demon. 7,</i> les faux pas, les erreurs ; πταίεσθαι τὸ ἀληθὲς αὐτοῖς εἴωθε, EL. <i>N.A. 2, 15, litt</i>. la vérité a coutume d’être pour eux l’occasion de faux pas, <i>càd</i>. ils n’atteignent pas d’ordinaire la vérité ;<br><b>   II <i>intr</i>.<br>      1</b> se heurter contre, donner contre : πρός τι, XÉN. <i>An. 4, 2, 3 ;</i> POL. <i>31, 19, 5,</i> contre qqe ch. (un rocher, une pierre, <i>etc</i>.) ; <i>fig</i>. πρός τινι, ESCHL. <i>Pr. 926 ;</i> PLAT. <i>Rsp. 553</i> b ; <i>ou</i> περί τινι, HDT. <i>9, 101, m. sign. ;</i><br><b>      2</b> <i>p. suite,</i> broncher, échouer, ne pas réussir : ἔν τινι, DÉM. <i>321, 8 ; ou</i> περί τι, PLAT. <i>Theæt. 160</i> d, en qqe ch. ; <i>ou avec un simple dat. :</i> τοῖς ὅλοις, POL. <i>3, 48, 4,</i> échouer en tout, perdre tout ; τῇ μάχῃ, POL. <i>17, 14, 13, ou</i> περὶ τὴν μάχην, POL. <i>2, 39, 8,</i> échouer dans un combat, éprouver un échec, une défaite ; <i>abs</i>. échouer (<i>p. opp. à</i> κατορθοῦν, réussir), DÉM. <i>23 fin ;</i> PLUT. <i>Cato mi. 69 ; ou</i> être malheureux (<i>p. opp. à</i> εὐτυχεῖν) ; πταίειν ὑπό τινος, POL. <i>5, 93, 2,</i> être malheureux par le fait de qqn ;<br><b>      3</b> se tromper <i>ou</i> être trompé : τῇ διανοίᾳ, PLAT. <i>Theæt. 160</i> d, commettre une méprise, une erreur.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πταιω - πταίω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Jacques (3)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4418":"<h1>pterna</h1>\n<p>Strong n° 4418 <i>Prononciation [pter'-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le talon (du pied)</li>\n<li>lever le talon contre quelqu'un\n<ol type=\"a\">\n<li>nuire à quelqu'un par tromperie (figure empruntée soit à « donner un coup de pied », ou au lutteur faisant trébucher son antagoniste)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πτέρνα, ης (ἡ) :<br>      1</b> talon, IL. <i>22, 397 ;</i> ESCHL. <i>Ch. 209 ;</i> DÉM. <i>88, 2 ;</i> ARSTT. <i>H.A. 1, 15, 6 ;</i><br><b>      2</b> <i>p. anal</i>. partie inférieure d’une chose (d’une tour, LYC. <i>442 ;</i> d’une machine, POL. <i>8, 8, 2 ;</i> d’un mât, ATH. <i>374</i> f).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πτέρνη, IL. LYC. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>cf. sscr</i>. pârsh<i>n</i>is.</span></span><br><br>\n➁ <b>πτέρνα, ης (ἡ)</b> <i>c</i>. πέρνα, BATR. <i>37 ; cf</i>. πτόλις, πτόλεμος, <i>etc</i>.<br>\n<b>πέρνα, ης (ἡ)</b> = <i>lat</i>. perna, jambon, STR. <i>162 ;</i> ATH. <i>657</i> e.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτερνα - πτέρνα</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4419":"<h1>pterugion</h1>\n<p>Strong n° 4419 <i>Prononciation [pter-oog'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une aile, une petite aile</li>\n<li>toute extrémité pointue\n<ol type=\"a\">\n<li>des nageoires de poissons</li>\n<li>d'une partie de vêtement qui pend en forme d'aile</li>\n<li>du sommet du temple à Jérusalem, le faîte</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτερύγιον, ου (τὸ)</b> <span>[ῠ]</span><br><b>A</b> petite aile, POL. <i>27, 9, 4 ;</i><br><b>B</b> <i>p. anal. :</i><br><b>   I</b> <i>t. d’hist. nat. :</i><br><b>      1</b> nageoire de poisson, ARSTT. <i>H.A. 1, 5, 7, etc. ; p. anal</i>. appendice semblable à une nageoire <i>chez certains crabes,</i> ARSTT. <i>H.A. 4, 1, 7 ;</i> extrémité de la queue <i>chez certains crustacés,</i> ARSTT. <i>H.A. 1, 5, 10, etc. ;</i><br><b>      2</b> aile du nez, GAL. <i>8, 591 ;</i><br><b>      3</b> membrane qui se forme sur la cornée de l’œil, DIOSC. <i>1, 147, 151 ;</i> GAL. <i>7, 322 ;</i><br><b>      4</b> excroissance charnue sur les ongles, DIOSC. <i>5, 5, 122 ;</i><br><b>   II</b> frange d’une étoffe, ARSTT. <i>Aud. 35 ;</i> SPT. <i>Num. 15, 38 ; Ruth 3, 9 ; ou</i> d’une cotte d’armes, DH. <i>Comp. p. 251 ;</i><br><b>   III</b> pièce d’une machine de siège, POL. <i>27, 9, 4 ; particul</i>. ailette, rebord, bords <i>ou</i> lèvres d’une rainure, HÉRON ; glissières de la batterie d’une machine de jet, PHIL. BYZ. ;<br><b>   IV</b> pinacle d’un temple, NT. <i>Matth. 4, 5 ; Luc. 4, 9 ;</i> JOS. <i>A.J. 15, 11, 5</i>.<br><span><b>Étym</b>. πτέρυξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτερυγιον - πτερύγιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4420":"<h1>pterux</h1>\n<p>Strong n° 4420 <i>Prononciation [pter'-oox]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une aile : d'oiseau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτέρυξ, υγος (ἡ)</b> <span>[ῠγ]</span><br><b>   I</b> aile, IL. <i>2, 316 ; au plur</i>. IL. <i>2, 462 ; 23, 875 ;</i> OD. <i>2, 149 ;</i> HDT. <i>2, 76 ;</i> PD. <i>P. 1, 11 ;</i> XÉN. <i>An. 1, 5, 3 ; fig</i>. EUR. <i>Ion 123 ;</i> SPT. <i>Ps. 17, 12 ; 103, 4 ; en parl. d’un vêtement dont on est couvert,</i> EUR. <i>Ion 1143 ; p. ext. :</i><br><b>      1</b> vol des oiseaux ; <i>fig</i>. vol, essor, <i>en parl. de gémissements,</i> SOPH. <i>El. 243 ;</i><br><b>      2</b> signe tiré du vol des oiseaux, présage, augure, CALL. <i>L. Pall. 124 ;</i><br><b>      3</b> volatile, oiseau, ANTH. <i>6, 11 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> nageoire de poisson, ARSTT. <i>Mir. 72 ;</i> EL. <i>N.A. 11, 24 ;</i> tentacule de certains mollusques, ARSTT. <i>H.A. 2, 14 ;</i> carapace de la tortue, NIC. <i>Al. 570 ;</i><br><b>      2</b> lobe du poumon, HPC. <i>Coac. 181 ;</i><br><b>      3</b> frange d’un vêtement, AR. <i>fr. 312 ;</i> PLUT. <i>Lyc. c. Num. 3, etc. ;</i><br><b>      4</b> <i>au plur</i>. appendices d’une cuirasse sur les parties creuses du corps, XÉN. <i>An. 4, 7, 15 ;</i><br><b>      5</b> tranchant aminci d’une épée, PLUT. <i>Alex. 16,</i> de la bouche du poisson ξίφος, EL. <i>N.A. 9, 40 ;</i><br><b>      6</b> partie d’une feuille d’arbre, TH. <i>H.P. 3, 9, 6 ;</i><br><b>      7</b> appendice en forme d’aile, <i>en parl. de l’Eubée placée comme une aile sinueuse devant le continent,</i> EUR. <i>I.A. 120, etc. ; ou d’une chaîne de montagnes,</i> MUS. <i>48 ;</i><br><b>      8</b> aile, embrasure d’une machine de jet, HÉRON.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. poét</i>. πτερύγεσσιν, IL.<br><span><b>Étym</b>. πτερόν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτερυξ - πτέρυξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4421":"<h1>ptenos</h1>\n<p>Strong n° 4421 <i>Prononciation [ptay-non']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui a des ailes</li>\n<li>ailé, volant\n<ol type=\"a\">\n<li>oiseaux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτηνός, ή, όν :<br>      1</b> qui vole, <i>en parl. d’oiseaux,</i> ESCHL. <i>Pr. 1022, etc. ;</i> SOPH. <i>Ph. 955, etc. ; de traits,</i> SOPH. <i>Ph. 166 ;</i> EUR. <i>H.f. 179 ; d’un char,</i> PLAT. <i>Phædr. 246</i> e ; <i>de l’amour,</i> EUR. <i>Hipp. 1275, etc. ;</i> τὰ πτηνά, ESCHL. <i>Ch. 591 ;</i> SOPH. <i>Aj. 168, etc. ;</i> PLAT. <i>Leg. 823</i> b, <i>etc</i>. les volatiles, les oiseaux ; <i>en parl. de songes,</i> EUR. <i>I.T. 571 ; de paroles,</i> EUR. <i>Or. 1176 ; en mauv. part, càd</i>. vain, léger, PLAT. <i>Leg. 717</i> c ;<br><b>      2</b> qui est en état de voler, EUR. <i>Tr. 147</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ός, PLAT. <i>Prot. 320</i> e. <i>Dor</i>. πτανός <span>[ᾱ]</span> PD. <i>fr. 74, 3 ;</i> SOPH. <i>Ph. 1146</i>.<br><span><b>Étym</b>. πέτομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτηνος - πτηνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4422":"<h1>ptoeo</h1>\n<p>Strong n° 4422 <i>Prononciation [pto-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>terrifier</li>\n<li>être terrifié</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτοέω-οῶ :<br>      1</b> frapper d’effroi, terrifier, CALL. <i>Del. 191 ;</i> ANTH. <i>7, 214 ; au pass</i>. être frappé d’effroi, OD. <i>22, 298 ;</i> ESCHL. <i>Ch. 535 ;</i> EUR. <i>El. 1255, etc. ;</i> ἐπί τινι, POL. <i>31, 19, 4,</i> par suite de qqe ch. ;<br><b>      2</b> frapper de démence, GEOP. <i>16, 1 ;</i><br><b>      3</b> frapper d’un transport de passion, <i>acc</i>. SAPPH. <i>fr. 2, 6 Bgk ;</i> A. RH. <i>1, 1232 ; au pass</i>. être saisi d’un transport de passion, THGN. <i>1012 ;</i> EUR. <i>I.A. 587, etc. ;</i> μετά τινα, HÉS. <i>O. 449 ;</i> εἴς τινα, LUC. <i>Am. 5,</i> pour qqn ; πρός τι, PLUT. <i>M. 989</i> a ; περί τι, PLUT. <i>M. 1128</i> b ; ἐπί τι, LUC. <i>Am. 23 ;</i> ἐπί τινι, PARTH. <i>4, 2,</i> pour qqn <i>ou</i> qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Épq</i>. πτοιέω, HÉS. A. RH. <i>ll. cc. ; ao. pass. 3 pl. épq</i>. ἐπτοίηθεν, OD. <i>l. c. Dor. ao. 3 sg</i>. ἐπτόασεν <span>[ᾱ]</span> SAPPH. <i>l. c. ; ao. pass. 2 sg</i>. ἐπτοάθης <span>[ᾱ]</span> EUR. <i>I.A. 587</i>.<br><span><b>Étym</b>. πτόα ; <i>cf</i>. πτήσσω, πτώσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτοεω - πτοέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> - « être étonné », (frappé par le tonnerre...), être saisi de terreur, d'une soudaine et effrayante angoisse ; mais, comme notre mot « étonner », souvent utilisé pour des circonstances beaucoup plus simples dans le langage populaire\n<br><br> - « terrifier », remplir de crainte\n<br><br> - « trembler », terme à prédominance physique\n<br><br> - « craindre », terme général, souvent utilisé pour un état prolongé</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4423":"<h1>ptoesis</h1>\n<p>Strong n° 4423 <i>Prononciation [pto'-ay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être effrayé, dans la terreur, épouvante, effroi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτόησις, εως (ἡ) :<br>      1</b> stupeur, épouvante, ARSTT. <i>G.A. 4, 5, 9 ;</i><br><b>      2</b> mouvement violent de l’âme, passion, CLÉARQ. (ATH. <i>670</i> c) ; PLAT. <i>Prot. 310</i> d, <i>Conv. 206</i> d, <i>Crat. 404</i> a ; PLUT. <i>M. 1026</i> c.<br><span><b>Étym</b>. πτοέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτοησις - πτόησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4424":"<h1>Ptolemais</h1>\n<p>Strong n° 4424 <i>Prononciation [ptol-em-ah-is']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ptolémaïs (Angl. Ptolemais) ou Acco = « guerrier »\n<ol><li>cité maritime de Phénicie, qui s'appelait Acco, et qui prit son nom d'un des premiers Ptolémées, qui en fut vainqueur en 103 av. J.C. et la reconstruisit encore plus belle. Elle reprit plus tard son nom d'Acco, transformé en Acre, puis Saint-Jean d'Acre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πτολεμαΐς, ΐδος (ἡ)</b> <span>[ᾱ]</span><br><b>      1</b> <i>adj. f</i>. de Ptolémée, Ptolémaïde, <i>tribu attique du nom de Ptolémée Philadelphe,</i> PAUS. <i>1, 5, 5 ;</i> ANTH. <i>7, 520, etc. ;</i><br><b>      2</b> fille de Ptolémée, PLUT. <i>Demetr. 32</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. Πτολεμαιΐς, CIA. <i>2, 966, 42 (peu après 191 av. J.C.) etc. ; et</i> Πτολεμαΐς, CIA. <i>2, 446, 72 (envir. 153 av. J.C.) etc. ; v. Meisterh. p. 26, 8</i>.<br><span><b>Étym</b>. Πτολεμαῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πτολεμαις - Πτολεμαΐς</font>\n<br><br>vient de Ptolemaios (Ptolemée, qui lui donna son nom)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4425":"<h1>ptuon</h1>\n<p>Strong n° 4425 <i>Prononciation [ptoo'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une pelle à vanner</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτύον, ου (τὸ)</b> pelle à vanner, <i>d’où</i> van, IL. <i>13, 588 ;</i> ESCHL. <i>fr. 206 Nauck ;</i> SOPH. <i>fr. 976 Nauck ;</i> THCR. <i>Idyl. 7, 156</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. dat. épq</i>. πτυόφιν, IL. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτυον - πτύον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4426":"<h1>pturo</h1>\n<p>Strong n° 4426 <i>Prononciation [ptoo'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>effrayer, effroi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτύρω</b> <span>(<i>f</i>. πτυρῶ, <i>ao</i>. ἔπτυρα, <i>ao.2 pass</i>. ἐπτύρην)</span> <span>[ῡ <i>prés. et ao. ;</i> ῠ <i>fut. et ao.2 pass</i>.]</span> effrayer, <i>d’où au pass</i>. s’effrayer : τι, PLAT. <i>Ax. 370</i> a ; <i>ou</i> πρός τι, PHIL. BYBL. (EUS. <i>P.E. 34</i> a) de qqe ch. ; <i>abs</i>. HPC. <i>600, 35 ; en parl. de chevaux,</i> DS. <i>2, 19 ;</i> PLUT. <i>Fab. 3</i>.<br><span><b>Étym</b>. <i>cf</i>. πτοέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτυρω - πτύρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4427":"<h1>ptusma</h1>\n<p>Strong n° 4427 <i>Prononciation [ptoos'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>salive, crachat</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτύσμα, ατος (τὸ)</b> crachat, <i>au plur</i>. HPC. <i>184</i> b ; <i>390, 55, etc. ;</i> POL. <i>8, 14, 5</i>.<br><span><b>Étym</b>. πτύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτυσμα - πτύσμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4428":"<h1>ptusso</h1>\n<p>Strong n° 4428 <i>Prononciation [ptoos'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>plier ensemble, rouler, enrouler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτύσσω</b> <span>(<i>f</i>. πτύξω, <i>ao</i>. ἔπτυξα, <i>pf. inus. ; pass. ao</i>. ἐπτύχθην, <i>pf</i>. πέπτυγμαι <i>et</i> ἔπτυγμαι)</span><br><b>      1</b> plier (un vêtement, <i>etc.) acc</i>. OD. <i>1, 439 ; 6, 111, 252, etc. ;</i><br><b>      2</b> <i>en gén</i>. replier, recourber : χεῖρας ἐπί τινι, SOPH. <i>O.C. 1611,</i> enlacer qqn de ses bras ; βιϐλίον, NT. <i>Luc. 4, 20,</i> fermer un livre ; <i>p. anal</i>. balancer (un javelot avant de le lancer) ;<br><b><i>Moy.</i></b> :<br><b>      1 <i>tr.</i></b> plier sur soi, s’envelopper de, <i>acc</i>. AR. <i>Nub. 267 ;</i><br><b>      2 <i>intr.</i></b> se plier, former des plis, SOPH. <i>fr. 791 Dind</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. πέπτυγμαι, ARSTT. <i>H.A. 4, 9, 10 ;</i> ἔπτυγμαι, APP. <i>Civ. 4, 72 ;</i> HDN <i>1, 17</i>.<br><span><b>Étym</b>. <i>p</i>. *πτύχ-ϳω ; <i>p.-ê. pré-grec, cf</i>. *πτύξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτυσσω - πτύσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4429":"<h1>ptuo</h1>\n<p>Strong n° 4429 <i>Prononciation [ptoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>crachat, salive</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτύω</b> <span>[ῡ]</span> <span>(<i>f</i>. πτύσω <i>et</i> πτύσομαι <span>[ῠ]</span>, <i>ao</i>. ἔπτυσα <span>[ῠ]</span>, <i>pf</i>. ἔπτυκα <span>[ῠ]</span> ; <i>pass. ao</i>. ἐπτύσθην, <i>ao.2</i> ἐπτύην, <i>pf</i>. ἔπτυσμαι)</span><br><b>      1</b> cracher : αἷμα, IL. <i>23, 697,</i> du sang ; <i>abs</i>. HDT. <i>1, 99 ;</i> XÉN. <i>Cyr. 8, 1, 24 ;</i> εἰς τὸν κόλπον, THCR. <i>Idyl. 6, 39, etc. ;</i> TH. <i>Char. 16 ;</i> LUC. <i>Nav. 15, etc. ou</i> ὑπὸ κόλπον, ANTH. <i>12, 229,</i> cracher dans son sein pour détourner un malheur ; τι, ANTH. <i>5, 170,</i> cracher qqe ch. ; <i>p. anal. en parl. de la mer,</i> THCR. <i>Idyl. 15, 133 ; d’où, en parl. d’un mât qui tombe en faisant jaillir l’eau,</i> ANTH. <i>9, 290 ; fig</i>. προσώπῳ, SOPH. <i>Ant. 1232,</i> exprimer son mépris par sa physionomie ; <i>abs</i>. πτύειν, <i>m. sign</i>. SOPH. <i>Ant. 658 ;</i><br><b>      2</b> <i>p. anal</i>. faire cracher, <i>en parl. de certains vins,</i> HPC. <i>358, 45</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf</i>. ἔπτυον <span>[ῠ]</span> THCR. <i>Idyl. 24, 19</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *tspi(e)uH-, cracher ; <i>cf</i>. ἀνα-, ἀπο-, δια-, ἐκ-πυτίζω, <i>lat</i>. spuō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτυω - πτύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4430":"<h1>ptoma</h1>\n<p>Strong n° 4430 <i>Prononciation [pto'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une chute, une chute à terre\n<ol type=\"a\">\n<li>métaph. un insuccès, une défaite, une calamité</li>\n<li>une erreur, tomber dans le péché</li>\n</ol>\n</li>\n<li>ce qui est tombé\n<ol type=\"a\">\n<li>le corps à terre de quelqu'un de mort ou tué, un cadavre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτῶμα, ατος (τὸ) :<br>   I</b> chute, ESCHL. <i>Pr. 919 ;</i> SOPH. <i>Ant. 1046 ;</i> EUR. <i>El. 686 ;</i> PLAT. <i>Lach. 181</i> b ; <i>fig</i>. revers, malheur, EUR. <i>H.f. 1228 ; particul</i>. échec, défaite, POL. <i>33, 12, 7 ;</i> erreur, NAZ. <i>2, 609 a Migne ;</i><br><b>   II</b> tout objet tombé :<br><b>      1</b> fruit tombé d’un arbre, LYS. (HARP.) ;<br><b>      2</b> ruine, débris, POL. <i>5, 4, 9 ; 5, 100, 6 ; 16, 31, 8 ;</i><br><b>      3</b> corps mort, cadavre, ESCHL. <i>Suppl. 662 ;</i> EUR. <i>Or. 1196, etc. ;</i> POL. <i>15, 14, 2, etc</i>.<br><span><b>Étym</b>. πίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτωμα - πτῶμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4431":"<h1>ptosis</h1>\n<p>Strong n° 4431 <i>Prononciation [pto'-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une chute, une ruine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτῶσις, εως (ἡ) :<br>   I</b> chute, <i>en parl. de pers. (Phaéthon</i>) POL. <i>2, 16, 13 ; en parl. de choses (foudre,</i> ARSTT. <i>Meteor. 1, 1, 2 ; dés,</i> PLAT. <i>Rsp. 604</i> c, <i>etc.) ; p. anal</i>. fléau qui s’abat sur qqn, SPT. <i>Ex. 30, 12 ;</i><br><b>   II</b> <i>t. de gr. :</i><br><b>      1</b> cas (<i>cf. lat</i>. casus) d’un nom, autre que le nominatif (τὸ ὄνομα) ARSTT. <i>Interpr. 2, 3, etc. ; qqf. en parl. de toute la déclinaison, nominatif compris,</i> ARSTT. <i>Poet. 20, 10 ;</i><br><b>      2</b> temps d’un verbe, autre que le présent, ARSTT. <i>Interpr. 3, 2 ;</i><br><b>      3</b> mode d’un verbe, <i>c</i>. ἔγκλισις, ARSTT. <i>Categ. 1, 5 ; 7, 7 ; Interpr. 2, 3 ; 3, 3 ;</i><br><b>      4</b> mot formé d’un autre, <i>comme l’adverbe de l’adjectif,</i> ARSTT. <i>Rhet. 2, 23, 2, etc. ;</i><br><b>   III</b> <i>t. de log</i>. mode dans certains syllogismes, ARSTT. <i>An. pr. 1, 26, 1</i>.<br><span><b>Étym</b>. πίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτωσις - πτῶσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4432":"<h1>ptocheia</h1>\n<p>Strong n° 4432 <i>Prononciation [pto-khi'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mendicité</li>\n<li>dans le N.T. pauvreté\n<ol type=\"a\">\n<li>la condition de quelqu'un privé de richesse et d'abondance</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτωχεία, ας (ἡ)</b> mendicité, pauvreté, AR. <i>Pl. 549 ;</i> PLAT. <i>Leg. 936</i> b ; LYS. <i>898, 9 ; au pl</i>. PLAT. <i>Rsp. 618</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πτωχηΐη, HDT. <i>3, 14</i>.<br><span><b>Étym</b>. πτωχεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτωχεια - πτωχεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4433":"<h1>ptocheuo</h1>\n<p>Strong n° 4433 <i>Prononciation [pto-khyoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être un mendiant, mendier, être pauvre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτωχεύω<br>      1</b> mendier, OD. <i>15, 309 ; 19, 73 ;</i> AR. <i>Nub. 921, etc. ;</i> ANT. <i>117, 22 ; avec un acc. de ch. :</i> δαῖτα, OD. <i>17, 11, 19,</i> mendier sa nourriture ; <i>avec un acc. de pers. :</i> τινά, THGN. <i>918,</i> mendier auprès de qqn ;<br><b>      2</b> être dans la pauvreté, ANTIPH. (<i>Com. fr. 3, 158</i>) ; PLAT. <i>Eryx. 394</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. itér</i>. πτωχεύεσκον, OD. <i>18, 2</i>.<br><span><b>Étym</b>. πτωχός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτωχευω - πτωχεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4434":"<h1>ptochos</h1>\n<p>Strong n° 4434 <i>Prononciation [pto-khos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réduit à la mendicité, à demander l'aumône</li>\n<li>privé de richesse, d'influence, de position, d'honneur\n<ol type=\"a\">\n<li>humble, affligé, privé des vertus chrétiennes et des richesses éternelles</li>\n<li>sans secours</li>\n<li>pauvre, nécessiteux</li>\n</ol>\n</li>\n<li>manquant de toute chose\n<ol type=\"a\">\n<li>en considération de l'esprit\n<ol>\n<li>privé de la richesse de l'instruction et de la culture intellectuelle offertes par les écoles (les hommes de ces conditions suivent plus facilement l'enseignement de Christ et prouvent qu'ils sont capables d'obtenir le trésor céleste)</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πτωχός, ή, όν</b>, <i>litt</i>. qui se blottit <i>ou</i> se cache, <i>d’où</i> humble ; <i>p. ext. :</i><br><b>      1</b> pauvre, mendiant, OD. <i>14, 400 ; 18, 1 ; joint à</i> ἀλήμων, OD. <i>19, 74 ; à</i> ἀλαλήμενος, OD. <i>21, 327 ; cf</i>. HÉS. <i>O. 26 ;</i> HDT. <i>3, 14 ; au fém</i>. NT. <i>Marc. 5, 3 ; Luc. 6, 20, etc. ; p. ext</i>. pauvre en, dépourvu de, <i>gén</i>. ANTH. <i>9, 258 ;</i><br><b>      2</b> qui concerne un mendiant, de mendiant, SOPH. <i>O.C. 751</i>.<br><span>•<i> Cp</i>. -ότερος, TIMOCL. (ATH. <i>223</i> c), <i>ou</i> -ίστερος, AR. <i>Ach. 425 ;</i> <i>• Sup</i>. -ότατος, ANTH. <i>10, 50</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ός, ESCHL. <i>Ag. 1274 ;</i> SOPH. <i>O.C. 751</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec ; autrement R. indo-europ</i>. *pteh₂-(k)-, se blottir ; <i>cf</i>. πτώσσω, πτήσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πτωχος - πτωχός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n34 fois dans 34 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (5)</li>\n<li>Luc (10)</li>\n<li>Jean (4)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>Jacques (4)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4435":"<h1>pugme</h1>\n<p>Strong n° 4435 <i>Prononciation [poog-may']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le poing, la main serrée</li>\n<li>jusqu'au coude</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πυγμή, ῆς (ἡ) :<br>      1</b> poing, HPC. <i>Art. 833 ;</i> EUR. <i>I.T. 1368 ;</i> AR. <i>Vesp. 1384 ;</i><br><b>      2</b> lutte à coups de poing, pugilat, PLAT. <i>Leg. 795</i> b ; DÉM. <i>1408, 16 ;</i> πυγμῇ νικᾶν, IL. <i>23, 669 ; ou</i> πυγμὴν νικᾶν, EUR. <i>Alc. 1031,</i> vaincre au pugilat.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. πυγμά, PD. <i>O. 7, 30</i>.<br><span><b>Étym</b>. πύξ, <i>cf. lat</i>. pugnus.</span></span><br><br>\n➁ <b>πυγμῇ</b>, <i>dans la locut</i>. πυγμῇ νίψασθαι, NT. <i>Marc. 7, 3,</i> se laver avec soin <i>ou</i> souvent.<br><span><b>Étym</b>. <i>cf</i>. πυκινός, πυκνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυγμη - πυγμή</font>\n<br><br>vient de pux (le poing en tant qu'arme)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4436":"<h1>Puthon</h1>\n<p>Strong n° 4436 <i>Prononciation [poo'-thone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dans la mythologie Grecque, le nom du serpent ou dragon qui demeurait au pied du Mont Parnasse, qui, dit-on, gardait l'oracle de Delphe, et fut tué par Apollon.( à comparer avec la Pythie de Delphes )</li>\n<li>un esprit de divination</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πύθων, ωνος (ὁ)</b> <span>[ῡ]</span> Python :<br><b>   I</b> <i>serpent tué par Apollon,</i> EPHOR. (STR. <i>422</i>) ; PLUT. <i>M. 293</i> c ; APD. <i>1, 4, 1 ; p. suite :</i><br><b>      1</b> prophète inspiré par Apollon Pythien, NT. <i>Ap. 16, 16 ;</i> JOS. <i>Genes. 33</i> b ;<br><b>      2</b> ventriloque, PLUT. <i>M. 414</i> e ;<br><b>   II</b> <i>n. d’h. :</i><br><b>      1</b> <i>envoyé de Philippe de Macédoine,</i> ESCHN. <i>2, 125, etc. ;</i> DÉM. <i>7, 20 Baiter-Sauppe, etc. ;</i><br><b>      2</b> <i>général d’Alexandre le Grand,</i> EL. <i>V.H. 9, 16 ;</i> PLUT. <i>Alex. 76 ;</i><br><b>      3</b> <i>autres,</i> DÉM. <i>23, 119 Baiter-Sauppe, etc. ;</i> PLUT. <i>Pyrrh. 8 ;</i> LUC. <i>Demon. 15, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυθων - πύθων</font>\n<br><br>vient de Putho (nom de la région où Delphe, le siège du fameux oracle, était situé)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4437":"<h1>puknos</h1>\n<p>Strong n° 4437 <i>Prononciation [pook-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>épais, dense, compact\n<ol type=\"a\">\n<li>en référence au temps\n<ol>\n<li>fréquemment, souvent, qui revient</li>\n</ol>\n</li>\n<li>vigoureusement, diligemment</li>\n<li>souvent, plus fréquemment, le plus souvent</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυκνός, ή, όν :<br>   I</b> dru, serré, <i>d’où :</i><br><b>      1</b> dru, serré : στίχες πυκναί, IL. <i>7, 60,</i> rangs pressés ; πυκνὴ φάλαγξ, XÉN. <i>An. 2, 3, 3,</i> troupe serrée ; πυκνοὶ ἀλλήλοισι, IL. <i>13, 133, etc. ;</i> OD. <i>5, 480,</i> serrés les uns contre les autres ; <i>joint à</i> σταυροί : π. καὶ θαμέες, OD. <i>14, 12 ;</i> πυκνὰ πτερά, IL. <i>11, 545 ; 23, 879 ;</i> OD. <i>5, 33,</i> ailes dont le plumage est serré ;<br><b>      2</b> <i>p. suite,</i> épais : πυκνὴ θρίξ, XÉN. <i>Cyn. 4, 6 ;</i> PLAT. <i>Prot. 321</i> a, crinière <i>ou</i> chevelure épaisse ; <i>de même en parl. de bois, de buissons,</i> OD. <i>5, 471, etc. ; d’arbres,</i> XÉN. <i>An. 4, 8, 2, etc. ; de nuages,</i> IL. <i>16, 298 ;</i> HÉS. <i>O. 551, etc. ;</i><br><b>      3</b> dense, compact, <i>en parl. de l’air,</i> PLUT. <i>M. 396</i> a, <i>etc. ; d’où</i> d’une trame solide, d’un tissu serré, <i>càd</i>. solide, <i>en parl. d’un vêtement,</i> OD. <i>14, 521 ; d’un os,</i> PLAT. <i>Tim. 75</i> a, <i>etc. ;</i><br><b>      4</b> <i>particul</i>. solidement joint, étroitement fermé, <i>en parl. d’une maison,</i> IL. <i>10, 267, etc. ;</i> OD. <i>7, 81 ; de portes,</i> IL. <i>14, 167, 339 ;</i><br><b>      5</b> <i>t. de mus</i>. τὸ πυκνόν, sorte d’intervalle, ARISTOX. <i>El. harm. p. 24 ;</i> PLUT. <i>M. 1135</i> b ; <i>les différents degrés s’appelaient</i> βαρύπυκνοι (<i>s.-e</i>. τόνοι) le ton le plus bas de l’intervalle ; ὀξύπυκνοι, le ton le plus élevé ; μεσόπυκνοι, le ton du milieu, A. QUINT. <i>1, 6, p. 12 ;</i><br><b>      6</b> <i>fig</i>. consistant, fort, <i>adv</i>., πυκνὰ μάλα στενάχων, IL. <i>18, 318,</i> gémissant fortement ; <i>cf</i>. IL. <i>24, 480 ;</i> OD. <i>11, 88 ; 19, 516 ;</i><br><b>      7</b> <i>fig. en parl. de l’intelligence,</i> réfléchi, avisé, sage : πυκνὰ μήδεα, IL. <i>3, 208, etc</i>. pensées sages, prudentes, avisées ; <i>rar. en prose,</i> πυκνὴ διάνοια, PLAT. <i>Rsp. 568</i> a, intelligence avisée ; <i>postér. en parl. de pers</i>. PD. <i>O. 13, 73 ;</i> SOPH. <i>Ph. 854, etc. ;</i><br><b>   II</b> <i>au sens partitif,</i> fréquent, qui se succède sans interruption : κύλικες π. SOPH. <i>fr. 563 Dind</i>. coupe sur coupe ; πυκναὶ λιθάδες, OD. <i>14, 36,</i> nombreuses pierres lancées ; π. κροτησμός, ESCHL. <i>Sept. 561,</i> applaudissements répétés ; ἐν πυκνῷ τροχῷ κυκλεῖσθαι, SOPH. <i>fr. 713 Dind</i>. tourner sur une roue dont les tours se succèdent sans cesse ; πολλαὶ καὶ π. οἰκήσεις, PLAT. <i>Criti. 117</i> e, habitations nombreuses et rapprochées ; π. σφυγμός, PLUT. <i>M. 136</i> f, pouls fréquent, <i>p. opp. à</i> μανός ; <i>adv</i>., πήρη πυκνὰ ῥωγαλέη, OD. <i>13, 438,</i> besace qui a déchirure sur déchirure ; πυκνὸν ἀναπνεῖν, ARSTT. <i>Rhet. 1, 2,</i> avoir une respiration fréquente ; <i>cf</i>. XÉN. <i>An. 5, 9, 8, etc. ;</i> PLAT. <i>Rsp. 501</i> b, <i>etc</i>.<br><span>•<i> Cp</i>. πυκνότερος, XÉN. <i>Vect. 5, 1</i>. <i>• Sup</i>. -ότατος, PD. <i>O. 13, 73 ;</i> XÉN. <i>Hipp. 5, 6 ;</i> AR. <i>Av. 429, etc. ;</i> TH. <i>H.P. 1, 5, 5</i>.<br><span><b>Étym</b>. <i>pour</i> πυκινός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυκνος - πυκνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4438":"<h1>pukteuo</h1>\n<p>Strong n° 4438 <i>Prononciation [pook-te-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être un boxeur, frapper</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυκτεύω<br>   I.1</b> se battre à coups de poing, DÉM. <i>51, 24 ;</i><br><b>      2</b> asséner un coup de poing, EUR. <i>Cycl. 229 ;</i><br><b>      3</b> <i>particul. en parl. d’athlètes,</i> lutter au pugilat, XÉN. <i>Lac. 4, 6 ;</i> PLAT. <i>Gorg. 456</i> d ;<br><b>   II</b> <i>p. ext</i>. combattre, <i>en gén</i>. HLD. <i>10, 31</i>.<br><span><b>Étym</b>. πύκτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυκτευω - πυκτεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4439":"<h1>pule</h1>\n<p>Strong n° 4439 <i>Prononciation [poo'-lay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une porte\n<ol type=\"a\">\n<li>de grande dimension\n<ol>\n<li>dans le mur d'une cité</li>\n<li>d'un palais</li>\n<li>d'une ville</li>\n<li>du temple</li>\n<li>d'une prison</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>les portes de l'enfer (comme d'une grande prison)</li>\n<li>métaph. l'accès ou l'entrée dans tout état</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πύλη, ης (ἡ)</b> <span>[ῠ]</span><br><b>A</b> <i>n. comm. :</i><br><b>   I</b> <i>au sg</i>. battant d’une porte, HDT. <i>3, 156 ; p. ext</i>. porte, SOPH. <i>Ant. 1186, etc. ;</i> THCR. <i>Idyl. 2, 160 ;</i> POL. <i>7, 18, 4, etc. ;</i><br><b>   II</b> <i>au pl</i>. porte :<br><b>      1</b> d’une maison <i>ou</i> d’un palais, SOPH. <i>Ant. 1186, etc. ;</i> XÉN. <i>Cyr. 7, 5, 25, etc. ;</i><br><b>      2</b> porte d’une tente, SOPH. <i>Aj. 11 ;</i><br><b>      3</b> porte d’un camp, IL. <i>7, 339 ; 12, 175 ;</i> XÉN. <i>An. 6, 3, 1 ;</i><br><b>      4</b> porte de tours, de fortifications, ESCHL. <i>Sept. 30 ;</i> XÉN. <i>Cyr. 7, 4, 6 ;</i><br><b>      5</b> porte d’une ville, IL. <i>18, 275 ;</i> HÉS. <i>Sc. 272 ;</i> XÉN. <i>An. 5, 10, 8 ;</i> PLAT. <i>Ax. 364</i> d, <i>etc. ; particul. à Troie,</i> les portes Scées (<i>v</i>. Σκαιαί) IL. <i>3, 145, etc. ;</i><br><b>   III</b> <i>p. ext</i>. passage, <i>en gén. càd. :</i><br><b>      1</b> <i>en parl. de désignations géograph. :</i> isthme, <i>en parl. de l’isthme de Corinthe,</i> PD. <i>O. 9, 129, etc. ;</i> XÉN. <i>Ages. 2, 17, etc. ;</i> détroit, <i>en parl. des colonnes d’Hercule,</i> PD. (STR. <i>170), etc. ; du Bosphore de Thrace,</i> ESCHL. <i>Pr. 729, etc. ;</i> canal, <i>càd</i>. écluse, HDT. <i>3, 117, etc. ;</i> défilé d’une montagne, HDT. <i>5, 52, etc. ;</i> STR. <i>520, 613, etc. ;</i><br><b>      2</b> <i>en parl. d’organes,</i> conduit (de l’oreille) PLAT. <i>Conv. 218</i> b ; entrée de la veine-porte dans le foie, EUR. <i>El. 828 ;</i> PLAT. <i>Tim. 71</i> c ; ARSTT. <i>H.A. 1, 17, etc. ;</i><br><b>      3</b> <i>fig</i>. πύλας ὕμνων ἀναπιτνάμεν, PD. <i>O. 6, 44,</i> ouvrir les portes du chant ; ἀρρήτων ἐπέων πύλαι, BACCHYL. <i>fr. 5, 4,</i> portes des paroles secrètes ; πύλαι πολέμου, PLUT. <i>Cæs. 33,</i> portes de la guerre, <i>etc. ;</i><br><b>B</b> <i>n. de lieu :</i> Πύλαι, ῶν (αἱ) Pyles, <i>litt</i>. « les Portes » :<br><b>      1</b> <i>c</i>. Θερμόπυλαι, HDT. <i>7, 176, 201 ;</i> DÉM. <i>327, 6 ;</i> PLUT. <i>M. 867</i> d, <i>etc. ;</i><br><b>      2</b> Πύλαι τῆς Κιλικίας, XÉN. <i>An. 1, 4, 4,</i> les Portes de Cilicie, <i>défilé entre la Cilicie et la Syrie ;</i><br><b>      3</b> Πύλαι Ἀμανικαί, ARR. <i>An. 2, 7,</i> défilé du mt Amanos ;<br><b>      4</b> Πύλαι Βαϐυλώνιαι <i>ou simpl</i>. Πύλαι, XÉN. <i>An. 1, 5, 5,</i> portes de Babylonie, <i>càd. défilé qui conduit d’Arabie en Babylonie</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυλη - πύλη</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4440":"<h1>pulon</h1>\n<p>Strong n° 4440 <i>Prononciation [poo-lone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une grande porte : d'un palais</li>\n<li>la face avant d'une maison, l'endroit où quelqu'un entre par la porte, le porche, le vestibule</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυλών, ῶνος (ὁ)</b> <span>[ῠ]</span> grande porte, <i>d’où :</i><br><b>      1</b> porche, portail, ARSTT. <i>Mund. 6, 9 ;</i> ANTH. <i>11, 203 ;</i><br><b>      2</b> <i>p. suite,</i> vestibule, POL. <i>4, 18, 2, etc. ; particul. en parl. d’un temple,</i> DS. <i>1, 47 ;</i> PLUT. <i>Tim. 12, etc. ; à Rome,</i> atrium, LUC. <i>Nigr. 23, etc</i>.<br><span><b>Étym</b>. πύλη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυλων - πυλών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (5)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G4441":"<h1>punthanomai</h1>\n<p>Strong n° 4441 <i>Prononciation [poon-than'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'enquérir, s'informer</li>\n<li>s'assurer de, par une interrogation</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυνθάνομαι</b> <span>(<i>f</i>. πεύσομαι, <i>ao.2</i> ἐπυθόμην, <i>pf</i>. πέπυσμαι)</span><br><b>   I</b> chercher à savoir, s’enquérir, s’informer, <i>joint à</i> ἐρωτῶ, PLAT. <i>Hipp. mi. 372</i> c ; <i>à</i> ἀνερέσθαι, SOPH. <i>O.R. 1305 ; p. opp. à</i> οἶδα, XÉN. <i>Cyr. 4, 1, 3 ;</i> πᾶσαν π. ἀλήθειαν περί τινος, SOPH. <i>Tr. 91,</i> s’enquérir de toute la vérité sur qqe ch. ; τι παρά τινος π. PLAT. <i>Gorg. 455</i> c, s’enquérir de qqe ch. auprès de qqn ; π. τινος, XÉN. <i>An. 5, 5, 25, etc</i>. s’informer au sujet de qqn <i>ou</i> de qqe ch. ; <i>avec l’acc. de la chose dont on s’enquiert :</i> π. τι, ATT. s’enquérir de qqe ch. ; <i>avec le gén. de la pers. auprès de laquelle on s’enquiert,</i> τὸν ἄνδρα πυνθάνου τῶν ὁδοιπόρων ἁπάντων, AR. <i>Ach. 204,</i> enquiers-toi de l’homme auprès de tous les voyageurs ; τῶν ἑπομένων ἐπυνθάνετο ὁποίοις οὐ χρὴ θηρίοις πελάζειν, XÉN. <i>Cyr. 1, 4, 7,</i> il s’informait auprès de ceux de sa suite de quelles bêtes sauvages il fallait ne pas s’approcher ; <i>de même</i> παρά τινος π. HDT. <i>3, 68 ;</i> XÉN. <i>Cyr. 1, 6, 23, etc</i>. s’informer auprès de qqn ; <i>avec une prop. d’interrog. indir. avec</i> εἰ, SOPH. <i>O.C. 993 ;</i> XÉN. <i>Hell. 4, 1, 11 ; avec</i> τί, PLAT. <i>Soph. 216</i> d ; PLUT. <i>Demetr. 27, etc. ; avec</i> ποῦ, SOPH. <i>Tr. 66 ; avec</i> ὅπως, XÉN. <i>An. 3, 1, 6, etc. ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> apprendre en s’informant, être informé de <i>ou</i> que, savoir, <i>joint à</i> ἴδον, OD. <i>23, 40 ; à</i> ᾔδη, IL. <i>13, 674 ;</i> ὡς ἐγὼ πυνθάνομαι, comme j’apprends, comme j’entends dire, <i>p. suite :</i> comme je sais, HDT. <i>1, 22 ;</i> THC. <i>7, 12 ;</i> DÉM. <i>160, 15 ;</i> πυνθανόμενος, sachant, HDT. <i>1, 69, 153 ;</i> ἐπυνθανόμην, je savais, XÉN. <i>An. 2, 1, 4, etc. ; avec l’acc</i>. π. τι, IL. <i>15, 179 ; 18, 530 ;</i> HDT. <i>1, 153 ;</i> ESCHL. <i>Ch. 526 ;</i> PLAT. <i>Charm. 153</i> c, apprendre qqe ch. ; <i>avec un acc. suivi d’une prop. relat. :</i> τινὰ π. ὅτι, <i>etc</i>. HDT. <i>7, 157, etc</i>. apprendre que qqn, <i>etc. ; avec un acc. accompagné d’un part</i>. εἰ πυθόμην ταύτην ὁδὸν ὁρμαίνοντα, OD. <i>4, 732,</i> si j’avais appris qu’il entreprenait ce voyage ; ἐὰν θνῄσκοντας ἢ τετρωμένους πύθησθε, ESCHL. <i>Sept. 243,</i> si vous apprenez qu’ils soient morts ou blessés ; π. τὸν Κῦρον προσελαύνοντα, XÉN. <i>An. 1, 5, 16,</i> apprendre que Cyrus s’avance ; <i>avec une prop. inf</i>. XÉN. <i>An. 7, 6, 11 ;</i> ISOCR. <i>388</i> d ; <i>avec le gén. de la pers. ou de la chose, sur laquelle on apprend qqe ch. ;</i> ὄφρα πύθηαι πατρός, OD. <i>3, 15,</i> afin que tu aies des nouvelles de ton père ; <i>cf</i>. IL. <i>15, 224, etc. ;</i> OD. <i>8, 12, etc. ; avec le gén. accompagné d’un part. :</i> π. Πατρόκλοιο θανόντος, IL. <i>17, 377,</i> apprendre la mort de Patrocle ; π. τῆς Πύλου κατειλημμένης, THC. <i>4, 6,</i> apprendre la prise de Pylos ; π. περί τινος, HDT. <i>2, 75 ;</i> THC. <i>1, 95 ;</i> PLAT. <i>Leg. 952</i> a, apprendre qqe ch. au sujet de qqn <i>ou</i> de qqe ch. ; <i>avec le gén. de la pers., de laquelle on apprend qqe ch. ;</i> π. τινος, ESCHL. <i>Suppl. 185 ;</i> SOPH. <i>O.R. 333, etc</i>. apprendre de qqn ; π. τινός τι, HDT. <i>1, 122 ;</i> AR. <i>Ran. 1417, etc</i>. apprendre qqe ch. de qqn ; τινὸς π. ὅτι, XÉN. <i>An. 6, 1, 23, etc</i>. apprendre de qqn que, <i>etc. ;</i> π. τι παρά τινος, apprendre qqe ch. de qqn, HDT. <i>2, 91 ;</i> XÉN. <i>Cyr. 4, 1, 2 ;</i> PLAT. <i>Conv. 179</i> e, <i>etc. ;</i> π. ἔκ τινος, SOPH. <i>O.C. 1266 ;</i> ἀπό τινος, ESCHL. <i>Ch. 737, m. sign. ;</i><br><b>      2</b> <i>p. suite,</i> s’apercevoir de, remarquer : ἐπύθοντο μετὰ Τρώεσσιν Ἄρηα, IL. <i>5, 702,</i> ils s’aperçurent qu’Arès était parmi les Troyens.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. dans Hom. seul</i>. OD. <i>2, 315. Impf. épq</i>. πυνθανόμην, OD. <i>13, 256. Fut. 2 sg. épq</i>. πεύσεαι, IL. <i>18, 19 ; fut. dor</i>. πευσοῦμαι, THCR. <i>Idyl. 3, 51. Ao.2 impér</i>. πυθοῦ, MÉN. <i>4, 321 Meineke ; ion</i>. πύθευ, HDT. <i>3, 68 (var</i>. πυθεῦ) ; <i>sbj. 2 sg. épq</i>. πύθηαι, IL. <i>5, 351 ; opt. 3 sg. épq</i>. πεπύθοιτο, IL. <i>6, 50, etc. ; 3 pl. ion</i>. πυθοίατο, IL. <i>1, 257 ;</i> SOPH. <i>O.C. 921. Pf. 2 sg</i>. πέπυσαι, PLAT. <i>Prot. 310</i> b ; <i>épq</i>. πέπυσσαι, OD. <i>11, 494. Pl.q.pf. 3 sg. épq</i>. πέπυστο, IL. <i>13, 521 ; 3 duel</i> πεπύσθην, IL. <i>17, 377</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *b<sup>h</sup>eud<sup>h</sup>-, devenir éveillé <i>ou</i> attentif ; <i>cf. sscr</i>. buddhá- « illuminé ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυνθανομαι - πυνθάνομαι</font>\n<br><br>vient du mot putho (qui se présente comme une variante à certains temps)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (7)</li>\n</ul>\n</td></tr>\n</table>","G4442":"<h1>pur</h1>\n<p>Strong n° 4442 <i>Prononciation [poor]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>feu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πῦρ (τὸ)</b> <span>[ῡ <i>aux cas monosyll.,</i> ῠ <i>aux cas dissyll</i>.]</span><br><b>   I</b> feu, <i>au propre,</i> IL. <i>9, 211, etc. ;</i> OD. <i>7, 7, etc. ;</i> πῦρ καίειν, IL. <i>8, 521 ;</i> OD. <i>21, 176, etc</i>. faire <i>ou</i> entretenir du feu ; ἀνακαίειν, OD. <i>7, 13, m. sign. ;</i> ἅπτειν, AR. <i>Nub. 768 ;</i> ἐξάπτειν, PLUT. <i>M. 138</i> b, allumer du feu ; φυσᾶν, AR. <i>Lys. 293, etc</i>. souffler du feu ; ῥιπίζειν, PLUT. <i>Flam. 21,</i> attiser du feu ; σϐεννύναι, IL. <i>16, 293 ; 21, 381 ;</i> HDT. <i>1, 86 ;</i> PLUT. <i>M. 138</i> b ; ἀποσϐεννύναι, XÉN. <i>Lac. 13, 3,</i> éteindre du feu ; νηυσὶ πῦρ ἐμϐάλλειν, IL. <i>15, 597,</i> lancer du feu sur des navires ; πῦρ ἐν κλισίῃσι βάλλειν, OD. <i>8, 501,</i> lancer du feu dans des tentes ;<br><b>   II</b> <i>particul. :</i><br><b>      1</b> feu d’un bûcher, IL. <i>15, 340 ; 22, 342 ; 23, 45 ; 24, 38 ;</i><br><b>      2</b> feu d’un sacrifice, IL. <i>9, 220 ;</i> OD. <i>3, 341, 446 ;</i> ESCHL. <i>Ch. 863 ;</i> SOPH. <i>fr. 340 Dind. ;</i> PLAT. <i>Criti. 120</i> a, <i>etc. ;</i><br><b>      3</b> feu du foyer, IL. <i>10, 418 ;</i> OD. <i>5, 59 ;</i> ESCHL. <i>Ag. 1435, etc. ; en parl. du feu sacré de Vesta,</i> POLL. <i>1, 7 ; à Rome,</i> PLUT. <i>Num. 9 ;</i><br><b>      4</b> feu du ciel, foudre <i>ou</i> éclair, ESCHL. <i>Pr. 1046,</i> SOPH. <i>O.R. 470, etc. ;</i><br><b>      5</b> feu du soleil, <i>p. opp. à</i> χειμών, PD. <i>P. 3, 87 ;</i> PLAT. <i>Leg. 865</i> b ; <i>d’où en gén</i>. éclat des astres, SOPH. <i>Ant. 1146 ;</i><br><b>      6</b> lueur des torches, des flambeaux, SOPH. <i>Ant. 964 ;</i><br><b>      7</b> feux de camp, feux de bivouac, <i>au plur</i>. IL. <i>8, 509, 554, etc. ;</i> HDT. <i>4, 134 ;</i> THC. <i>8, 102 ;</i> XÉN. <i>Cyr. 3, 3, 25, etc. ;</i><br><b>      8</b> feu du regard, éclat des yeux, IL. <i>13, 474 ;</i> OD. <i>19, 446 ;</i> HÉS. <i>Sc. 145 ;</i><br><b>      9</b> feu de la fièvre, AR. (<i>Com. fr. 2, 1191</i>) ; πῦρ ἄγριον, HPC. <i>1215</i> h, <i>c</i>. ἐρυσίπελας ;<br><b>   III</b> <i>fig. :</i><br><b>      1</b> feu, <i>c. symbole de force irrésistible,</i> IL. <i>6, 182 ; 11, 596 ; 17, 565 ; 20, 371 ;</i> SOPH. <i>O.R. 177 ;</i> XÉN. <i>Hell. 5, 7, 12, etc. ;</i><br><b>      2</b> <i>c. symbole de destruction, de dévastation,</i> SOPH. <i>Ph. 927 ;</i> EUR. <i>Hec. 608, etc. ;</i><br><b>      3</b> feu de la passion, ardeur d’un sentiment, SOPH. <i>El. 888 ;</i> CALL. <i>Ep. 26, 5, etc. ;</i><br><b>      4</b> <span><i>prov</i>. ἐν πυρὶ γενέσθαι</span>, IL. <i>2, 340,</i> s’en aller en feu, périr <i>ou</i> être perdu ; <span>φεύγοντα καπνὸν δουλείας εἰς πῦρ δεσποτείας ἐμπίπτειν</span>, PLAT. <i>Leg. 569</i> b, fuir la fumée de la servitude pour tomber dans le feu du despotisme, <i>càd</i>. tomber de Charybde en Scylla ; <span>πῦρ ἐπὶ πῦρ ἐγχεῖν, ἄγειν</span>, <i>etc</i>. CRAT. (<i>Com. fr. 1, 26</i>) ; AR. <i>fr. 389 Dind. ;</i> PLAT. <i>Leg. 666</i> a, verser du feu sur du feu, <i>càd</i>. rendre le mal pour le mal ; <span>μετά τινος διὰ πυρὸς βαδίζειν</span>, AR. <i>Lys. 133,</i> aller à travers le feu avec qqn, partager avec lui tous les périls ; <i>cf</i>. XÉN. <i>Œc. 21, 7 ; Conv. 4, 16 ; mais</i> <span>διὰ πυρὸς μολεῖν τινι</span>, EUR. <i>El. 1182 ; ou</i> ἔρχεσθαί τινι, EUR. <i>Andr. 487,</i> avoir une haine ardente pour qqn ; <span>εἰς πῦρ ἅλλεσθαι</span>, XÉN. <i>Mem. 1, 3, 9,</i> sauter dans le feu, ne reculer devant aucun danger ; <span>εἰς πῦρ ξαίνειν</span>, PLAT. <i>Leg. 780</i> c, frapper dans le feu, faire de vaines tentatives.<br><span><b><span class=\"arrow\"></span></b> <i>Plur</i>. τὰ πυρά, IL. <i>8, 509, 554 ; 9, 77, etc. ;</i> HDT. <i>4, 134 ;</i> THC. <i>8, 102, etc. ; dat</i>. πυροῖς, XÉN. <i>An. 7, 2, 18 ; poét</i>. πυροῖσι, ESCHL. <i>Ch. 485 ; sg</i>. πυρόν, HDN GR. <i>π. μ. λ. 38, rejeté par</i> EUST. <i>729, 63. Par distension</i> πύυρ, SIM. <i>fr. 59. Orig. étrangère sel</i>. PLAT. <i>Crat. 410</i> a.<br><span><b>Étym</b>. <i>indo-europ</i>. *peh₂-ur-, ph₂-uen-s, feu ; <i>avec th. r/n, cf. all</i>. Feuer, Funke.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρ - πῦρ</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n72 fois dans 71 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (12)</li>\n<li>Marc (6)</li>\n<li>Luc (7)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (25)</li>\n</ul>\n</td></tr>\n</table>","G4443":"<h1>pura</h1>\n<p>Strong n° 4443 <i>Prononciation [poo-rah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un feu, un tas de bois qui flambe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πυρά, ῶν (τὰ)</b> <i>pl. dε</i> .<br><br>\n➁ <b>πυρά, ᾶς (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> bûcher, IL. <i>1, 52 ; 4, 99, etc. ;</i> PD. <i>N. 9, 86 ;</i> SOPH. <i>Tr. 1254, etc. ;</i> PLAT. <i>Rsp. 391</i> b, <i>etc. ;</i><br><b>      2</b> autel pour les sacrifices, HDT. <i>7, 167 ;</i> EUR. <i>Ion 1258, etc. ; d’où</i> feu qui brûle sur cet autel, HDT. <i>2, 39 ;</i><br><b>      3</b> <i>p. ext</i>. amas de matières combustibles, faisceau de torches, <i>etc</i>. DS. <i>17, 36</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. πυρή, IL. HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. πῦρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρα - πυρά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4444":"<h1>purgos</h1>\n<p>Strong n° 4444 <i>Prononciation [poor'-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une tour</li>\n<li>une structure fortifiée, s'élevant à une certaine hauteur, pour repousser une attaque hostile ou permettre à un veilleur de voir dans toutes directions</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πύργος, ου (ὁ) :<br>   I</b> tour (une) IL. <i>3, 153 ; 4, 462 ; 9, 574 ;</i> HÉS. <i>Sc. 242 ;</i> PLAT. <i>Criti. 116</i> a, <i>etc. ; en parl. de tours mobiles pour le siège des villes,</i> XÉN. <i>Cyr. 6, 1, 53 ; 6, 2, 18, etc. ; p. ext. :</i><br><b>      1</b> enceinte garnie de tours, IL. <i>6, 386, 431 ;</i> OD. <i>6, 262 ;</i> EUR. <i>Hec. 1209 ; au plur</i>. IL. <i>7, 338 ; d’où</i> citadelle, rempart ; <i>fig. en parl. de pers., de guerriers, etc</i>. OD. <i>11, 556 ;</i> SOPH. <i>O.R. 1201 ;</i> EUR. <i>Alc. 311, etc. ;</i> POÈT. (PLUT. <i>M. 600</i> f) ;<br><b>      2</b> toute construction semblable à une tour ; <i>en parl. du refuge où vivait Timon,</i> PAUS. <i>1, 30, 4, etc. ;</i><br><b>      3</b> étage supérieur d’une maison, gynécée, DÉM. <i>1156, 10 ;</i> PHILSTR. <i>863 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> sorte de bataillon carré, IL. <i>4, 334, 347 ;</i><br><b>      2</b> cornet à dés, ANTH. <i>9, 482</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυργος - πύργος</font>\n<br><br>apparemment un mot primaire (« un bourg »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4445":"<h1>puresso</h1>\n<p>Strong n° 4445 <i>Prononciation [poo-res'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être malade avec de la fièvre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυρέσσω</b>, <i>att</i>. <b>πυρέττω</b> <span>[ῠ]</span> <span>(<i>impf</i>. ἐπύρεσσον, <i>att</i>. -εττον, <i>f</i>. πυρέξω, <i>ao</i>. ἐπύρεξα, <i>pf</i>. πεπύρεχα ; <i>pf. pass</i>. πεπύρεγμαι)</span> avoir la fièvre, HPC. <i>Aph. 1245 ;</i> EUR. <i>Cycl. 228 ;</i> AR. <i>Vesp. 813 ;</i> ESCHN. <i>69, 43, etc</i>.<br><span><b>Étym</b>. πυρετός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρεσσω - πυρέσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4446":"<h1>puretos</h1>\n<p>Strong n° 4446 <i>Prononciation [poo-ret-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chaleur ardente</li>\n<li>fièvre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυρετός, οῦ (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> chaleur ardente, ardeur, IL. <i>22, 31 ;</i><br><b>      2</b> fièvre, AR. <i>Vesp. 1038 ;</i> PLAT. <i>Tim. 86</i> a ; ARSTT. <i>Probl. 1, 55, 3</i>.<br><span><b>Étym</b>. πῦρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρετος - πυρετός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4447":"<h1>purinos</h1>\n<p>Strong n° 4447 <i>Prononciation [poo'-ree-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ardent</li>\n<li>brillant comme du feu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πύρινος, η, ον</b> <span>[ῠῐ]</span> de feu, enflammé, ardent, ARSTT. <i>An. 3, 13, 1, etc. ; fig</i>. POL. <i>35, 1, 1</i>.<br><span><b>Étym</b>. πῦρ.</span><br><br>\n➁ <b>πύρινος, η, ον</b> <span>[ῡῐ]</span> de blé, de froment, EUR. <i>fr. 374 Nauck ;</i> XÉN. <i>An. 4, 5, 31 ;</i> ARSTT. <i>Probl. 1, 37, 1 ;</i> TH. <i>H.P. 8, 4, 1</i>.<br><span><b>Étym</b>. πυρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρινος - πύρινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4448":"<h1>puroo</h1>\n<p>Strong n° 4448 <i>Prononciation [poo-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>brûler avec feu, mettre en feu, allumer\n<ol type=\"a\">\n<li>être en feu, brûler\n<ol>\n<li>être irrité, indigné</li>\n</ol>\n</li>\n<li>produire de la chaleur\n<ol>\n<li>plein de feu, ardent, allumé\n<ol type=\"a\">\n<li>de flèches enduites de substances inflammables et qui sont enflammées</li>\n</ol>\n</li>\n<li>fondu par le feu et purifié</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυρόω-ῶ</b> <span>[ῠ]</span> mettre en feu, brûler, <i>d’où :</i><br><b>      1</b> consumer par le feu, <i>acc</i>. HDT. <i>7, 8 ; 8, 102 ;</i> ESCHL. <i>fr. 265 Dind. ;</i> SOPH. <i>Ant. 286 ;</i> EUR. <i>Cycl. 590, etc. ; au pass</i>. être consumé par le feu, PD. <i>P. 11, 50 ;</i> EUR. <i>Andr. 400, etc. ; ou</i> fondre sous l’action du feu, ARSTT. <i>Probl. 21, 10 ; fig</i>. consumer par la passion, enflammer, embraser ; <i>au pass</i>. être enflammé, être ardent, brûler, ESCHL. <i>Ag. 481 ;</i> τινι, ANTH. <i>12, 87,</i> brûler de désirs pour qqn ;<br><b>      2</b> produire du feu, ARSTT. <i>P.A. 2, 2, 26, d’où au pass</i>. devenir du feu, s’enflammer, brûler, PLAT. <i>Tim. 51</i> b, <i>etc. ;</i> ARSTT. <i>Cæl. 3, 8, 11, etc. ;</i><br><b>      3</b> atteindre par le feu, <i>d’où au pass</i>. être affecté par le feu, <i>en parl. de l’or,</i> ARSTT. <i>Meteor. 3, 6, 14 ;</i><br><b>      4</b> purifier par le feu, THCR. <i>Idyl. 24, 95 ; en parl. de l’or,</i> NT. <i>Apoc. 3, 18 ; fig. en parl. de pers</i>. SPT. <i>Ps. 17, 31 ; 119, 140 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἐπυρωσάμην)</span> placer sur le bûcher qqn des siens, <i>acc</i>. ANTH. <i>7, 466</i>.<br><span><b>Étym</b>. πῦρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυροω - πυρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4449":"<h1>purrhazo</h1>\n<p>Strong n° 4449 <i>Prononciation [poor-hrad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>devenir embrasé, virer au rouge, être rouge</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυρράζω</b>, être d’un rouge ardent, être roux, NT. <i>Matth. 16, 2</i>.<br><span><b>Étym</b>. πυρρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρραζω - πυρράζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G4450":"<h1>purrhos</h1>\n<p>Strong n° 4450 <i>Prononciation [poor-hros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ayant la couleur du feu, rouge</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πυρρός, ά, όν :<br>      1</b> d’un rouge de feu, PLAT. <i>Tim. 68</i> c ; <i>en parl. d’un vêtement,</i> HDT. <i>3, 139 ; des lèvres,</i> THCR. <i>Idyl. 6, 3 ;</i> τὸ πυρρόν, AR. <i>Eccl. 329,</i> rouge ardent ;<br><b>      2</b> roux, <i>en parl. de pers. qui ont les cheveux rouges,</i> HDT. <i>4, 108 ;</i> HPC. <i>292, 44 ; des cheveux,</i> ARSTT. <i>Probl. 38, 2 ; de la barbe,</i> ESCHL. <i>Pers. 316, etc. ;</i><br><b>      3</b> fauve, <i>en parl. d’animaux</i> (lion, EUR. <i>H.f. 361 ;</i> ARSTT. <i>G.A. 5, 6, 1 ;</i> bœuf, PLUT. <i>M. 363</i> b, <i>etc. ;</i> chien, XÉN. <i>Cyn. 4, 7, etc</i>.).<br><span>•<i> Cp</i>. πυρρότερος, SYMM. <i>Jer. 4, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. πυρσός, ESCHL. <i>Pers. 316 ;</i> EUR. <i>Ph. 32, etc. ;</i> <i>• Sup</i>. πυρσότατος, PLUT. <i>Pel. 22. Dans les inscr. att. la forme assimilée,</i> Πύρρος (<i>n. d’h.) dès le 5<sup>e</sup> siècle av. J.C., v</i>. Πύρρος.<br><span><b>Étym</b>. <i>incert. ; cf</i>. πυρσός².</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρρος - πυρρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4451":"<h1>purosis</h1>\n<p>Strong n° 4451 <i>Prononciation [poo'-ro-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une combustion\n<ol type=\"a\">\n<li>le feu par lequel les métaux sont fondus</li>\n<li>par une figure provenant d'un feu d'affineur : calamités ou épreuves qui éprouvent le caractère</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πύρωσις, εως (ἡ)</b> <span>[ῠ]</span> action de brûler :<br><b>   I</b> <i>en gén</i>. combustion, TH. <i>H.P. 5, 9, 1 ; p. anal</i>. inflammation, fièvre, DIOSC. <i>2, 150 ;</i> SEXT. <i>114, 10 Bkk. etc. ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> action de faire cuire, ARSTT. <i>Probl. 21, 12 ;</i> TH. <i>H.P. 7, 7, 2, etc. ;</i><br><b>      2</b> action de faire bouillir, ARSTT. <i>Meteor. 4, 3 ;</i> MNÉSITH. (ATH. <i>357</i> d) ;<br><b>      3</b> action d’échauffer, <i>d’où</i> chaleur, ardeur, ARSTT. <i>Meteor. 2, 9, 7 ; 3, 1, 9 ;</i> PLUT. <i>M. 658</i> a.<br><span><b>Étym</b>. πυρόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πυρωσις - πύρωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4452":"<h1>-po</h1>\n<p>Strong n° 4452 <i>Prononciation [po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>néanmoins, même</li>\n<li>utilisé seulement en composé avec , , , , </li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πώς</b>, <i>adv. indéf. enclitique,</i> de quelque façon, en quelque manière, <i>d’ord. en un sens d’atténuation :</i><br><b>      1</b> <i>avec un adj. :</i> τοιαῦτα… πώς, ATT. à peu près de telles choses ;<br><b>      2</b> <i>avec un adv. :</i> ὧδέ πως, XÉN. <i>Cyr. 3, 3, 7,</i> à peu près ainsi ; ἄλλως πως, XÉN. <i>An. 3, 1, 20,</i> de qqe autre manière ; μόγις πως, PLAT. <i>Prot. 328</i> d, avec quelque peine ;<br><b>      3</b> <i>particul. après</i> γάρ, ESCHL. <i>Pr. 224, Ch. 958, etc. ;</i><br><b>      4</b> avec un verbe : ἠθάς εἰμί πως τῶν τῆσδε μύθων, SOPH. <i>El. 372,</i> j’ai quelque habitude de l’entendre parler ; πράσσοντές πως ταῦτα, THC. <i>2, 3,</i> faisant à peu près ainsi ; <i>cf</i>. HDT. <i>3, 78, 108, 150 ;</i> THC. <i>3, 20, etc. ;</i><br><b>      5</b> <i>après les conj. conditionnelles ou les négations :</i> εἴ πως, ATT. ; αἴ πως, OD. <i>14, 460,</i> si de quelque manière ; οὔ πως, IL. <i>4, 158 ;</i> OD. <i>20, 392 ; ou en un seul mot</i> οὔπως (<i>v. ce mot) ; att</i>. μή πως, ESCHL. <i>Ag. 1249 ; ou en un seul mot</i> μήπως ATT. en aucune façon ;<br><b>      6</b> <i>en relation avec un autre</i> πως <i>ou avec</i> ἄλλως : πὼς μὲν… πὼς δέ, THÉM. ; πὼς μὲν… ἄλλως δέ, ARSTT. <i>Pol. 2, 5 ;</i> tantôt… tantôt.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κώς, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. *πός, <i>d’où</i> ποῦ, ποῖ, <i>etc</i>.</span></span><br><br>\n➁ <b>πῶς</b>, <i>adv. interr. :</i> comment ? de quelle manière ? ;<br><b>A</b> <i>dans l’interr. directe :</i><br><b>   I.1</b> comment : πῶς δοκεῖς ; PLAT. <i>Pol. 309</i> c, que t’en semble ? <i>qqf. avec l’expression de la colère,</i> πῶς ἐθέλεις ; IL. <i>4, 26,</i> comment peux-tu vouloir cela ? πῶς νῦν οὐκ εἰμί σοι χωλός, δυσώδης ; <i>etc</i>. SOPH. <i>Ph. 1031,</i> comment ne suis-je plus tout à coup pour toi estropié et puant ? <i>etc. ;</i><br><b>      2</b> <i>qqf. au sens de</i> pourquoi ? πῶς οὖν οὐ καὶ σὺ παιδεύεις ; XÉN. <i>Conv. 2, 10,</i> comment, <i>càd</i>. pourquoi n’enseignes-tu pas aussi ? <i>Avec l’expression de l’étonnement, particul. dans la locut</i>. πῶς εἶπας ; comment dis-tu ? qu’est-ce ? entends-je bien ? <i>ou :</i> que dis-tu là ! ESCHL. <i>Pers. 798 ;</i> SOPH. <i>El. 407, O.C. 1099, etc. ; de même</i> πῶς λέγεις ; SOPH. <i>Ph. 1407 ;</i> πῶς φῇς ; ESCHL. <i>Ag. 268 ;</i> SOPH. <i>O.R. 746 ;</i> πῶς ταῦτ' ἔλεξας ; ESCHL. <i>Pers. 793 ;</i> πῶς τοῦτ' εἶπας αὖ ; PLAT. <i>Pol. 309</i> c ; <i>en répétant un mot de l’affirmation précédente :</i> ἢν εὑρεθῇς ἐς τήνδε μὴ δίκαιος ὤν ; — πῶς μὴ δίκαιος ; SOPH. <i>Tr. 412,</i> si tu as été convaincu d’être un messager infidèle envers elle ; — comment, infidèle ? <i>joint à un autre mot interrog. :</i> πῶς ἐκ τίνος νεώς ποτε ἥκετε ; EUR. <i>Hel. 1543,</i> comment, avec quel vaisseau êtes-vous arrivés ici ? <i>particul. dans la locut. :</i> πῶς τί ; πῶς τί ἄρ' ἂν ἀγωνιζοίμεθα ; PLAT. <i>Hipp. ma. 298</i> a, pourquoi et de quelle façon pourrions-nous nous quereller ? πῶς τί τοῦτο λέγεις ; PLAT. <i>Tim. 22</i> b, que dis-tu là et comment ? <i>càd</i>. pourquoi ? <i>cf</i>. PLAT. <i>Theæt. 146</i> d, <i>208</i> e, <i>etc. ; avec le gén</i>. πῶς ἔχει πλήθους ; PLAT. <i>Gorg. 451</i> c, qu’en est-il de la foule ? <i>Avec les verbes indiquant achat, vente, etc., au sens de combien</i> = πόσου : Μεγαροῖ πῶς ὁ σῖτος ὤνιος ; AR. <i>Ach. 758,</i> combien vend-on le blé à Mégare ? τὰ ἄλφιθ' ὑμῖν πῶς ἐπώλουν ; AR. <i>Eq. 480,</i> combien vous vendaient-ils la farine ? ;<br><b>   II</b> <i>joint à des particules :</i><br><b>      1</b> πῶς ἄν, <i>épq</i>. πῶς κε (κεν) <i>avec l’opt. :</i> πῶς κ' ἔοι ; IL. <i>14, 333,</i> comment serait-ce ? quel air cela aurait-il ? <i>avec l’indic. d’un temps historique :</i> πῶς δέ κεν Ἕκτωρ Κῆρας ὑπεξέφυγεν θανάτοιο, εἰ μή οἱ ἤντετ' Ἀπόλλων ; IL. <i>22, 202,</i> comment Hector aurait-il échappé aux génies de la mort, si Apollon ne se fût présenté à lui ? <i>particul. avec l’opt. pour exprimer un souhait :</i> πῶς ἂν θάνοιμι ; SOPH. <i>Aj. 388,</i> comment pourrais-je mourir ? <i>càd</i>. oh ! puissé-je mourir ! oh ! si je pouvais mourir ! <i>cf</i>. SOPH. <i>Ph. 794, O.R. 765 ;</i> EUR. <i>Med. 97, etc. ; de même chez Homère :</i> πῶς κέν μοι ὑποσχόμενος τελέσειας μῦθον ἐμόν ; OD. <i>15, 195,</i> après m’avoir fait une telle promesse, comment pourrais-tu la tenir ? <i>postér. au même sens,</i> πῶς <i>avec le sbj</i>. M. ANT. <i>9, 40 ;</i> ARR. <i>Epict. 4, 10, 10 ;</i><br><b>      2</b> πῶς γάρ ; comment donc ? comment cela ? <i>d’ordin. en un sens nég. (s.-e</i>. cela ne peut pas arriver) : πῶς γάρ τοι δώσουσι γέρας Ἀχαιοί ; IL. <i>1, 123,</i> comment donc les Achéens te feront-ils un présent ? <i>cf</i>. IL. <i>10, 61 ;</i> OD. <i>10, 337 ; 19, 325 ;</i> πῶς γὰρ κάτοιδα ; SOPH. <i>Ph. 250,</i> comment pourrais-je donc te connaître ? <i>abs</i>. πῶς γάρ ; comment donc ? comment cela ? <i>d’ord. avec idée d’invraisemblance ou d’impossibilité :</i> κἀγὼ μὲν οὐκ ἔδρασα, οὐδ' αὖ σύ· πῶς γάρ ; SOPH. <i>El. 911,</i> pour moi je ne l’ai pas fait, ni toi non plus : comment cela se pourrait-il en effet ? <i>au même sens, avec atténuation,</i> πῶς γὰρ ἄν ; PLAT. <i>Soph. 237</i> c, <i>Parm. 150</i> a, <i>etc. ;</i><br><b>      3</b> πῶς δέ ; mais comment ? <i>particul. avec idée de colère, de dépit, etc. :</i> πῶς δὲ σὺ νῦν μέμονας ; IL. <i>21, 481,</i> mais comment as-tu donc pu oser ! <i>cf</i>. OD. <i>18, 31 ;</i><br><b>      4</b> πῶς δή ; comment donc ? comment en vérité ? IL. <i>4, 351 ; 18, 364 ;</i> OD. <i>22, 231 ;</i> ESCHL. <i>Ag. 543, etc. ; abs</i>. SOPH. <i>El. 1400 ;</i> πῶς δῆτα ; <i>m. sign. ;</i> ESCHL. <i>Ag. 1210 ;</i> SOPH. <i>O.R. 592, etc. ; abs</i>. PLAT. <i>Gorg. 469</i> b ;<br><b>      5</b> <i>avec</i> καί : καὶ πῶς ; et comment ? <i>pour marquer l’impatience, d’ord. avec idée de nég. :</i> καὶ πῶς σιωπῶ ; EUR. <i>Or. 1025,</i> et comment me tairais-je ? <i>càd</i>. je ne puis pourtant pas me taire ; <i>cf</i>. ESCHL. <i>Ch. 178, 532, etc. ; abs</i>. καὶ πῶς ; comment serait-ce possible ? <i>càd</i>. cela est impossible <i>ou</i> incroyable, PLAT. <i>Theæt. 163</i> d, <i>Phil. 21</i> d, <i>etc. ; avec atténuation</i> καὶ πῶς ἄν ; PLAT. <i>Theæt. 188</i> c, <i>etc. ; invers</i>. πῶς καί ; comment donc seulement ? comment seulement aussi ? πῶς καὶ πέπρακται παίδων φόνος ; EUR. <i>Ph. 1354,</i> comment donc le meurtre des enfants s’est-il accompli ? <i>cf</i>. ESCHL. <i>Pers. 721 ;</i><br><b>      6</b> πῶς νῦν, comment maintenant ? que penses-tu maintenant de cela ? OD. <i>18, 223 ;</i><br><b>      7</b> πῶς οὔ ; <i>ou</i> πῶς οὐχί ; comment ne pas ? comment ne serait-ce pas ainsi (<i>lat</i>. quidni ?) ; πῶς οὐ δεινὰ εἴργασθε ; THC. <i>3, 66,</i> comment n’avez-vous pas commis là une action affreuse ? <i>càd</i>. comment pouvez-vous prétendre que vous n’avez pas commis, <i>etc. ?</i> πῶς οὐκ ἀδικεῖς ; DÉM. <i>317, 13, litt</i>. comment n’as-tu pas tort, <i>càd</i>. tu as tort sans aucun doute ; <i>abs</i>. πῶς δ' οὔ ; comment donc ne pas ? forcément, PLAT. <i>Rsp. 457</i> b ; πῶς δ' οὐχί ; SOPH. <i>O.R. 1015, etc. ;</i> πῶς γὰρ οὔ ; SOPH. <i>El. 865 ;</i> PLAT. <i>Gorg. 487</i> b, <i>etc. m. sign. ; qqf. entre parenthèses,</i> SOPH. <i>O.R. 567 ;</i> de même πῶς γὰρ οὔ ; ESCHL. <i>Ch. 754 ;</i> SOPH. <i>El. 1307, etc. ; avec atténuat. :</i> πῶς δ' οὐκ ἄν ; ESCHL. <i>Pr. 759 ;</i><br><b>      8</b> πῶς οὖν ; comment maintenant, comment donc ? ESCHL. <i>Suppl. 297 ;</i> XÉN. <i>Mem. 1, 2, 64 ; abs</i>. EUR. <i>Hipp. 598, 1261 ; Med. 1376 ;</i> PLAT. <i>Theæt. 188</i> c ; DÉM. <i>379, 15, etc. ;</i><br><b>      9</b> πῶς ποτε ; comment donc ? enfin ? SOPH. <i>Ph. 688, O.R. 1210, 10 ;</i> πῶς τε ; comment cependant ? <i>dans la locut</i>. πῶς τ' ἄρα <i>ou</i> πῶς τ' ἄρ <i>avec le sbj</i>. IL. <i>18, 188 ;</i> OD. <i>3, 22 ; avec l’opt</i>. IL. <i>11, 837 ;</i><br><b>B</b> <i>dans l’interr. indir</i>. comment : μένω ἀκοῦσαι πῶς ἀγὼν κριθήσεται, ESCHL. <i>Eum. 677,</i> je reste pour savoir comment se décidera la lutte ; <i>cf</i>. XÉN. <i>Cyr. 1, 4, 3 ; Mem. 1, 2, 36 ;</i> PLAT. <i>Gorg. 451</i> c ;<br><b>C</b> <i>au sens d’une exclamation :</i> comment ! comme ! NT. <i>Marc. 10, 23 ; Matth. 21, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κῶς, HDT. <i>2, 22</i>.<br><span><b>Étym</b>. <i>adv. de</i> *πός, <i>d’où</i> ποῦ, ποῖ, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πω - πώς</font>\n<br><br>Voir définition </td></tr>\n</table>","G4453":"<h1>poleo</h1>\n<p>Strong n° 4453 <i>Prononciation [po-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>troquer, vendre</li>\n<li>vendeurs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πωλέω-ῶ</b> <span>(<i>impf</i>. ἐπώλουν, <i>f</i>. πωλήσω, <i>ao</i>. ἐπώλησα, <i>pf. inus.)</i></span><i> litt</i>. tourner et retourner, <i>d’où</i> négocier, trafiquer, <i>p. suite :</i><br><b>      1</b> vendre, <i>acc., p. opp. à</i> ὠνεῖσθαι, HDT. <i>1, 165, etc. ; à</i> ἀποδίδοσθαι, XÉN. <i>Mem. 2, 5, 5 ;</i> τί τινι, XÉN. <i>Hier. 1, 13 ; ou</i> τι πρός τινα, HDT. <i>9, 80 ;</i> XÉN. <i>Œc. 1, 12,</i> qqe ch. à qqn ; <i>avec le n. de prix au gén. ou avec</i> πρός <i>et l’acc. :</i> τι ἀργυρίου, XÉN. <i>Mem. 1, 6, 13,</i> vendre qqe ch. à prix d’argent ; τι πρὸς ἀργύριον, TH. <i>H.P. 9, 6, 4,</i> vendre qqe ch. contre de l’argent ; <i>fig</i>. π. τῶν πόνων τἀγαθά, EPICH. (XÉN. <i>Mem. 2, 1, 20</i>) faire acheter les biens au prix de la peine ; <i>en mauv. part</i>. : vendre, livrer à prix d’or, <i>acc</i>. DÉM. <i>80, 29 ; 384, 28, etc. ; en parl. de pers</i>. AR. <i>Pax 633 ;</i><br><b>      2</b> affermer : τέλος, ESCHN. <i>16 fin,</i> un impôt ;<br><b><i>Moy.</i></b> trafiquer de soi, se vendre, se prostituer, SOL. (LYS.).<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 pl. dor</i>. πωλοῦντι, EPICH. <i>fr. 120 Ahrens. Impf. 3 sg. dor</i>. ἐπώλεε, HDT. <i>8, 105. Impf. itér. 3 sg</i>. πωλέεσκε, HDT. <i>1, 196. Pass. part. prés. poét</i>. πωλεύμενος, HOM. <i>Epigr. 14, 5. Moy. fut. au sens pass</i>. πωλήσομαι, EUB. <i>3, 241 Meineke</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *pel-, vendre ; <i>cf. all</i>. feil ; <i>autrement cf. p.-ê</i>. ἐμπολή, <i>v</i>. πέλω, πέλομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πωλεω - πωλέω</font>\n<br><br>vient probablement de pelomai (être occupé, commercer)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 20 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (3)</li>\n<li>Luc (6)</li>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4454":"<h1>polos</h1>\n<p>Strong n° 4454 <i>Prononciation [po'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un poulain, le petit d'un cheval</li>\n<li>une jeune créature\n<ol type=\"a\">\n<li>d'un jeune âne, ânon</li>\n<li>d'un poulain d'un âne</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πῶλος, ου (ὁ, ἡ) :<br>   I</b> poulain <i>ou</i> pouliche, jeune cheval, IL. <i>11, 681 ; 20, 222 ; 23, 246 ;</i> PD. <i>P. 2, 15 ;</i> ESCHL. <i>Pr. 1009 ;</i> XÉN. <i>Eq. 1, 1 ; p. ext</i>. cheval <i>en gén</i>. ESCHL. <i>fr. 341 ;</i> SOPH. <i>O.C. 313, 1062, etc. ;</i><br><b>   II</b> <i>p. ext. ou anal. :</i><br><b>      1</b> jeune animal (éléphant, chameau, <i>etc</i>.) ARSTT. <i>H.A. 9, 1, 32 ;</i> ANTH. <i>12, 238, etc. ;</i><br><b>      2</b> jeune fille (<i>cf</i>. δάμαλις, μόσχος, πόρτις, <i>etc</i>.) EUR. <i>Hipp. 546, Andr. 621, etc. ;</i> jeune femme, NIC. <i>Al. 65 ;</i> jeune garçon, ESCHL. <i>Ch. 794 ;</i> EUR. <i>Rhes. 386, etc. ;</i><br><b>      3</b> monnaie corinthienne avec l’empreinte d’un jeune cheval, EUR. <i>fr. 676 ;</i> EUB. <i>3, 242 Meineke</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *pōlH-, poulain ; <i>cf. all</i>. Fohlen.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πωλος - πῶλος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (4)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4455":"<h1>popote</h1>\n<p>Strong n° 4455 <i>Prononciation [po'-pot-e]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>jamais</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πώ·ποτε</b>, <i>adv. :</i><br><b>      1</b> quelquefois, une fois par hasard, <i>d’ord. après une nég. :</i> οὐ πώποτε, IL. <i>1, 106, 154 ; 3, 442, etc. ;</i> OD. <i>21, 123 ;</i> ATT. ; μὴ πώποτε, ATT. ; οὐδεπώποτε, μηδεπώποτε, ATT. jamais ; <i>sans nég. dans les prop. interr. équivalentes à une prop. négative :</i> ἤδη πώποτέ του ἤκουσας ; PLAT. <i>Rsp. 493</i> d, as-tu jamais entendu qqn ? <i>ou dans les prop. conditionnelles :</i> εἴ τις πώποτε, XÉN. <i>An. 5, 4, 6 ;</i> PLAT. <i>Theæt. 196</i> a, <i>etc</i>. si jamais qqn, <i>etc. ; enfin dans les prop. avec pron. indéfini :</i> ἄλλος ὅστις πώποτε, <i>etc</i>. PLAT. <i>Phædr. 258</i> d, tout autre homme qui jamais, <i>etc. ; cf</i>. PLAT. <i>Theæt. 144</i> a, <i>Rsp. 352</i> c, <i>etc. ; avec un art. accompagné d’un part. :</i> οἱ πώποτε ἁψάμενοι λόγων, PLAT. <i>Phædr. 279</i> a, ceux qui ont jamais mis la main à des discours ; οἱ πώποτε γενόμενοι, ISOCR. <i>215</i> e, ceux qui ont jamais existé ; <i>sans part. :</i> οἱ πώποτε προδόται, LYCURG. <i>167, 4,</i> les traîtres qui ont jamais existé ;<br><b>      2</b> quelquefois, en quelque façon : οὐ πώποτε, BATR. <i>178,</i> jamais en aucune façon.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. πώποκα <span>[ᾰ]</span> EPICH. (DL. <i>3, 10</i>).<br><span><b>Étym</b>. πώ, ποτέ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πωποτε - πώποτε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (4)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4456":"<h1>poroo</h1>\n<p>Strong n° 4456 <i>Prononciation [po-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recouvrir d'une peau épaisse, durci par le recouvrement d'une callosité</li>\n<li>métaph.\n<ol type=\"a\">\n<li>rendre le cœur dur, aigri</li>\n<li>devenir dur, engourdi, terne, perdre le pouvoir de compréhension</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πωρόω-ῶ :<br>   I</b> <i>au propre :</i><br><b>      1</b> rendre calleux, durcir, NYMPHIS (ATH. <i>549</i> b) ; TH. <i>H.P. 4, 15, 2 ;</i> EL. <i>V.H. 9, 13 ; au pass</i>. se durcir, <i>en parl. d’un calcul de la vessie,</i> HPC. <i>Aër. 286 ;</i><br><b>      2</b> <i>particul</i>. souder par un calus les parties d’un os fracturé, HPC. <i>Fract. 779 ;</i> DIOSC. <i>1, 89, 111 ;</i><br><b>   II</b> <i>fig</i>. endurcir, rendre insensible, <i>d’où au pass</i>. s’endurcir, s’aveugler, <i>en parl. du cœur,</i> NT. <i>Marc. 6, 52 ; Rom. 11, 7 ; en parl. des yeux,</i> devenir aveugle, être aveuglé, SPT. <i>Job 17, 7</i>.<br><span><b>Étym</b>. πῶρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πωροω - πωρόω</font>\n<br><br>vient apparemment de poros (une sorte de pierre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4457":"<h1>porosis</h1>\n<p>Strong n° 4457 <i>Prononciation [po'-ro-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recouvert d'une callosité</li>\n<li>obstruction du discernement mental, perception émoussée</li>\n<li>l'esprit de quelqu'un qui a été brusqué\n<ol type=\"a\">\n<li>opiniâtreté, endurcissement, dureté</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πώρωσις, εως (ἡ) :<br>      1</b> formation d’un calus, <i>particul</i>. soudure d’un os au moyen d’un calus, HPC. <i>Fract. 766, 792 ;</i><br><b>      2</b> <i>fig</i>. endurcissement, PLUT. <i>M. 281</i> d ; <i>fig</i>. NT. <i>Marc. 3, 5 ; Eph. 4, 18 ; Rom. 11, 25</i>.<br><span><b>Étym</b>. πωρόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πωρωσις - πώρωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4458":"<h1>-pos</h1>\n<p>Strong n° 4458 <i>Prononciation [poce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>par n'importe quel moyen, peut-être ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πώς</b>, <i>adv. indéf. enclitique,</i> de quelque façon, en quelque manière, <i>d’ord. en un sens d’atténuation :</i><br><b>      1</b> <i>avec un adj. :</i> τοιαῦτα… πώς, ATT. à peu près de telles choses ;<br><b>      2</b> <i>avec un adv. :</i> ὧδέ πως, XÉN. <i>Cyr. 3, 3, 7,</i> à peu près ainsi ; ἄλλως πως, XÉN. <i>An. 3, 1, 20,</i> de qqe autre manière ; μόγις πως, PLAT. <i>Prot. 328</i> d, avec quelque peine ;<br><b>      3</b> <i>particul. après</i> γάρ, ESCHL. <i>Pr. 224, Ch. 958, etc. ;</i><br><b>      4</b> avec un verbe : ἠθάς εἰμί πως τῶν τῆσδε μύθων, SOPH. <i>El. 372,</i> j’ai quelque habitude de l’entendre parler ; πράσσοντές πως ταῦτα, THC. <i>2, 3,</i> faisant à peu près ainsi ; <i>cf</i>. HDT. <i>3, 78, 108, 150 ;</i> THC. <i>3, 20, etc. ;</i><br><b>      5</b> <i>après les conj. conditionnelles ou les négations :</i> εἴ πως, ATT. ; αἴ πως, OD. <i>14, 460,</i> si de quelque manière ; οὔ πως, IL. <i>4, 158 ;</i> OD. <i>20, 392 ; ou en un seul mot</i> οὔπως (<i>v. ce mot) ; att</i>. μή πως, ESCHL. <i>Ag. 1249 ; ou en un seul mot</i> μήπως ATT. en aucune façon ;<br><b>      6</b> <i>en relation avec un autre</i> πως <i>ou avec</i> ἄλλως : πὼς μὲν… πὼς δέ, THÉM. ; πὼς μὲν… ἄλλως δέ, ARSTT. <i>Pol. 2, 5 ;</i> tantôt… tantôt.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κώς, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. *πός, <i>d’où</i> ποῦ, ποῖ, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πως - πώς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 7 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (2)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4459":"<h1>pos</h1>\n<p>Strong n° 4459 <i>Prononciation [poce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>comment, de quelle manière</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πῶς</b>, <i>adv. interr. :</i> comment ? de quelle manière ? ;<br><b>A</b> <i>dans l’interr. directe :</i><br><b>   I.1</b> comment : πῶς δοκεῖς ; PLAT. <i>Pol. 309</i> c, que t’en semble ? <i>qqf. avec l’expression de la colère,</i> πῶς ἐθέλεις ; IL. <i>4, 26,</i> comment peux-tu vouloir cela ? πῶς νῦν οὐκ εἰμί σοι χωλός, δυσώδης ; <i>etc</i>. SOPH. <i>Ph. 1031,</i> comment ne suis-je plus tout à coup pour toi estropié et puant ? <i>etc. ;</i><br><b>      2</b> <i>qqf. au sens de</i> pourquoi ? πῶς οὖν οὐ καὶ σὺ παιδεύεις ; XÉN. <i>Conv. 2, 10,</i> comment, <i>càd</i>. pourquoi n’enseignes-tu pas aussi ? <i>Avec l’expression de l’étonnement, particul. dans la locut</i>. πῶς εἶπας ; comment dis-tu ? qu’est-ce ? entends-je bien ? <i>ou :</i> que dis-tu là ! ESCHL. <i>Pers. 798 ;</i> SOPH. <i>El. 407, O.C. 1099, etc. ; de même</i> πῶς λέγεις ; SOPH. <i>Ph. 1407 ;</i> πῶς φῇς ; ESCHL. <i>Ag. 268 ;</i> SOPH. <i>O.R. 746 ;</i> πῶς ταῦτ' ἔλεξας ; ESCHL. <i>Pers. 793 ;</i> πῶς τοῦτ' εἶπας αὖ ; PLAT. <i>Pol. 309</i> c ; <i>en répétant un mot de l’affirmation précédente :</i> ἢν εὑρεθῇς ἐς τήνδε μὴ δίκαιος ὤν ; — πῶς μὴ δίκαιος ; SOPH. <i>Tr. 412,</i> si tu as été convaincu d’être un messager infidèle envers elle ; — comment, infidèle ? <i>joint à un autre mot interrog. :</i> πῶς ἐκ τίνος νεώς ποτε ἥκετε ; EUR. <i>Hel. 1543,</i> comment, avec quel vaisseau êtes-vous arrivés ici ? <i>particul. dans la locut. :</i> πῶς τί ; πῶς τί ἄρ' ἂν ἀγωνιζοίμεθα ; PLAT. <i>Hipp. ma. 298</i> a, pourquoi et de quelle façon pourrions-nous nous quereller ? πῶς τί τοῦτο λέγεις ; PLAT. <i>Tim. 22</i> b, que dis-tu là et comment ? <i>càd</i>. pourquoi ? <i>cf</i>. PLAT. <i>Theæt. 146</i> d, <i>208</i> e, <i>etc. ; avec le gén</i>. πῶς ἔχει πλήθους ; PLAT. <i>Gorg. 451</i> c, qu’en est-il de la foule ? <i>Avec les verbes indiquant achat, vente, etc., au sens de combien</i> = πόσου : Μεγαροῖ πῶς ὁ σῖτος ὤνιος ; AR. <i>Ach. 758,</i> combien vend-on le blé à Mégare ? τὰ ἄλφιθ' ὑμῖν πῶς ἐπώλουν ; AR. <i>Eq. 480,</i> combien vous vendaient-ils la farine ? ;<br><b>   II</b> <i>joint à des particules :</i><br><b>      1</b> πῶς ἄν, <i>épq</i>. πῶς κε (κεν) <i>avec l’opt. :</i> πῶς κ' ἔοι ; IL. <i>14, 333,</i> comment serait-ce ? quel air cela aurait-il ? <i>avec l’indic. d’un temps historique :</i> πῶς δέ κεν Ἕκτωρ Κῆρας ὑπεξέφυγεν θανάτοιο, εἰ μή οἱ ἤντετ' Ἀπόλλων ; IL. <i>22, 202,</i> comment Hector aurait-il échappé aux génies de la mort, si Apollon ne se fût présenté à lui ? <i>particul. avec l’opt. pour exprimer un souhait :</i> πῶς ἂν θάνοιμι ; SOPH. <i>Aj. 388,</i> comment pourrais-je mourir ? <i>càd</i>. oh ! puissé-je mourir ! oh ! si je pouvais mourir ! <i>cf</i>. SOPH. <i>Ph. 794, O.R. 765 ;</i> EUR. <i>Med. 97, etc. ; de même chez Homère :</i> πῶς κέν μοι ὑποσχόμενος τελέσειας μῦθον ἐμόν ; OD. <i>15, 195,</i> après m’avoir fait une telle promesse, comment pourrais-tu la tenir ? <i>postér. au même sens,</i> πῶς <i>avec le sbj</i>. M. ANT. <i>9, 40 ;</i> ARR. <i>Epict. 4, 10, 10 ;</i><br><b>      2</b> πῶς γάρ ; comment donc ? comment cela ? <i>d’ordin. en un sens nég. (s.-e</i>. cela ne peut pas arriver) : πῶς γάρ τοι δώσουσι γέρας Ἀχαιοί ; IL. <i>1, 123,</i> comment donc les Achéens te feront-ils un présent ? <i>cf</i>. IL. <i>10, 61 ;</i> OD. <i>10, 337 ; 19, 325 ;</i> πῶς γὰρ κάτοιδα ; SOPH. <i>Ph. 250,</i> comment pourrais-je donc te connaître ? <i>abs</i>. πῶς γάρ ; comment donc ? comment cela ? <i>d’ord. avec idée d’invraisemblance ou d’impossibilité :</i> κἀγὼ μὲν οὐκ ἔδρασα, οὐδ' αὖ σύ· πῶς γάρ ; SOPH. <i>El. 911,</i> pour moi je ne l’ai pas fait, ni toi non plus : comment cela se pourrait-il en effet ? <i>au même sens, avec atténuation,</i> πῶς γὰρ ἄν ; PLAT. <i>Soph. 237</i> c, <i>Parm. 150</i> a, <i>etc. ;</i><br><b>      3</b> πῶς δέ ; mais comment ? <i>particul. avec idée de colère, de dépit, etc. :</i> πῶς δὲ σὺ νῦν μέμονας ; IL. <i>21, 481,</i> mais comment as-tu donc pu oser ! <i>cf</i>. OD. <i>18, 31 ;</i><br><b>      4</b> πῶς δή ; comment donc ? comment en vérité ? IL. <i>4, 351 ; 18, 364 ;</i> OD. <i>22, 231 ;</i> ESCHL. <i>Ag. 543, etc. ; abs</i>. SOPH. <i>El. 1400 ;</i> πῶς δῆτα ; <i>m. sign. ;</i> ESCHL. <i>Ag. 1210 ;</i> SOPH. <i>O.R. 592, etc. ; abs</i>. PLAT. <i>Gorg. 469</i> b ;<br><b>      5</b> <i>avec</i> καί : καὶ πῶς ; et comment ? <i>pour marquer l’impatience, d’ord. avec idée de nég. :</i> καὶ πῶς σιωπῶ ; EUR. <i>Or. 1025,</i> et comment me tairais-je ? <i>càd</i>. je ne puis pourtant pas me taire ; <i>cf</i>. ESCHL. <i>Ch. 178, 532, etc. ; abs</i>. καὶ πῶς ; comment serait-ce possible ? <i>càd</i>. cela est impossible <i>ou</i> incroyable, PLAT. <i>Theæt. 163</i> d, <i>Phil. 21</i> d, <i>etc. ; avec atténuation</i> καὶ πῶς ἄν ; PLAT. <i>Theæt. 188</i> c, <i>etc. ; invers</i>. πῶς καί ; comment donc seulement ? comment seulement aussi ? πῶς καὶ πέπρακται παίδων φόνος ; EUR. <i>Ph. 1354,</i> comment donc le meurtre des enfants s’est-il accompli ? <i>cf</i>. ESCHL. <i>Pers. 721 ;</i><br><b>      6</b> πῶς νῦν, comment maintenant ? que penses-tu maintenant de cela ? OD. <i>18, 223 ;</i><br><b>      7</b> πῶς οὔ ; <i>ou</i> πῶς οὐχί ; comment ne pas ? comment ne serait-ce pas ainsi (<i>lat</i>. quidni ?) ; πῶς οὐ δεινὰ εἴργασθε ; THC. <i>3, 66,</i> comment n’avez-vous pas commis là une action affreuse ? <i>càd</i>. comment pouvez-vous prétendre que vous n’avez pas commis, <i>etc. ?</i> πῶς οὐκ ἀδικεῖς ; DÉM. <i>317, 13, litt</i>. comment n’as-tu pas tort, <i>càd</i>. tu as tort sans aucun doute ; <i>abs</i>. πῶς δ' οὔ ; comment donc ne pas ? forcément, PLAT. <i>Rsp. 457</i> b ; πῶς δ' οὐχί ; SOPH. <i>O.R. 1015, etc. ;</i> πῶς γὰρ οὔ ; SOPH. <i>El. 865 ;</i> PLAT. <i>Gorg. 487</i> b, <i>etc. m. sign. ; qqf. entre parenthèses,</i> SOPH. <i>O.R. 567 ;</i> de même πῶς γὰρ οὔ ; ESCHL. <i>Ch. 754 ;</i> SOPH. <i>El. 1307, etc. ; avec atténuat. :</i> πῶς δ' οὐκ ἄν ; ESCHL. <i>Pr. 759 ;</i><br><b>      8</b> πῶς οὖν ; comment maintenant, comment donc ? ESCHL. <i>Suppl. 297 ;</i> XÉN. <i>Mem. 1, 2, 64 ; abs</i>. EUR. <i>Hipp. 598, 1261 ; Med. 1376 ;</i> PLAT. <i>Theæt. 188</i> c ; DÉM. <i>379, 15, etc. ;</i><br><b>      9</b> πῶς ποτε ; comment donc ? enfin ? SOPH. <i>Ph. 688, O.R. 1210, 10 ;</i> πῶς τε ; comment cependant ? <i>dans la locut</i>. πῶς τ' ἄρα <i>ou</i> πῶς τ' ἄρ <i>avec le sbj</i>. IL. <i>18, 188 ;</i> OD. <i>3, 22 ; avec l’opt</i>. IL. <i>11, 837 ;</i><br><b>B</b> <i>dans l’interr. indir</i>. comment : μένω ἀκοῦσαι πῶς ἀγὼν κριθήσεται, ESCHL. <i>Eum. 677,</i> je reste pour savoir comment se décidera la lutte ; <i>cf</i>. XÉN. <i>Cyr. 1, 4, 3 ; Mem. 1, 2, 36 ;</i> PLAT. <i>Gorg. 451</i> c ;<br><b>C</b> <i>au sens d’une exclamation :</i> comment ! comme ! NT. <i>Marc. 10, 23 ; Matth. 21, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κῶς, HDT. <i>2, 22</i>.<br><span><b>Étym</b>. <i>adv. de</i> *πός, <i>d’où</i> ποῦ, ποῖ, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πως - πῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n103 fois dans 100 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (14)</li>\n<li>Luc (16)</li>\n<li>Jean (20)</li>\n<li>Actes (9)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (9)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Jean (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4460":"<h1>Rhaab</h1>\n<p>Strong n° 4460 <i>Prononciation [hrah-ab']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rahab = « large, spacieux, tumultueux »\n<ol><li>une prostituée de Jéricho</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">'Pααβ</font> &lt; רחב - <font face=\"Georgia\">Ῥαάβ</font>\n<br><br>Voir définition \n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4461":"<h1>rhabbi</h1>\n<p>Strong n° 4461 <i>Prononciation [hrab-bee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rabbi = « maître »\n<ol>\n<li>un grand monsieur, honorable</li>\n<li>Rabbi, titre utilisé par les Juifs en s'adressant à leurs enseignants</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραββι</font> &lt; רבי - <font face=\"Georgia\">ῥαββί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 15 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (4)</li>\n<li>Jean (8)</li>\n</ul>\n</td></tr>\n</table>","G4462":"<h1>rhabboni</h1>\n<p>Strong n° 4462 <i>Prononciation [hrab-bon-ee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>maître, chef, prince</li>\n<li>Rabbouni est un titre d'honneur qu'adressent l'aveugle et Marie à Jésus</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραββουνι</font> &lt; רבני - <font face=\"Georgia\">ῥαββουνί</font>\n<br><br>origine : Araméen</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4463":"<h1>rhabdizo</h1>\n<p>Strong n° 4463 <i>Prononciation [hrab-did'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>battre avec des verges</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥαϐδίζω</b>, battre avec une baguette : δένδρον, TH. <i>C.P. 1, 19, 4, etc</i>. gauler un arbre ; πυρούς, SPT. <i>Judith 6, 11 ; Ruth 2, 17,</i> battre du blé ; <i>abs</i>. frapper de verges, PHÉRÉCR. (<i>Com. fr. 2, 273</i>) ; carder, AR. <i>Lys. 587</i>.<br><span><b>Étym</b>. ῥάϐδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραβδιζω - ῥαβδίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4464":"<h1>rhabdos</h1>\n<p>Strong n° 4464 <i>Prononciation [hrab'-dos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un bâton, une canne pour la marche, un bout de bois, une verge, une branche</li>\n<li>une verge avec laquelle quelqu'un est battu</li>\n<li>un bâton\n<ol type=\"a\">\n<li>utilisé en voyage, ou pour s'appuyer, ou par les bergers</li>\n<li>appliqué aux choses\n<ol>\n<li>une verge de fer, indique la sévérité, la règle rigoureuse</li>\n<li>un sceptre royal</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥάϐδος, ου (ἡ) :<br>   I</b> baguette, <i>particul. :</i><br><b>      1</b> baguette, branche, sarment, TH. <i>H.P. 2, 1, 2 ;</i><br><b>      2</b> verge pour frapper, HDN <i>7, 9, 13 ;</i> XÉN. <i>Eq. 8, 4 ;</i> PLAT. <i>Leg. 700</i> c ; PLUT. <i>Alex. 51, etc. ;</i><br><b>      3</b> baguette magique de Circé, OD. <i>10, 238, 319, etc. ;</i> d’Athèna, OD. <i>16, 172 ;</i> de devin, HDT. <i>4, 67 ;</i><br><b>      4</b> canne à pêche, OD. <i>12, 251 ;</i><br><b>      5</b> baguette enduite de glu, gluau, AR. <i>Av. 527 ;</i><br><b>      6</b> bâton de commandement, sceptre, PD. <i>O. 9, 50 ;</i> PLAT. <i>Ax. 367</i> a ;<br><b>      7</b> bâton que portaient les rhapsodes, PD. <i>I. 4, 66 ;</i> CALL. <i>fr. 138 ;</i><br><b>      8</b> caducée d’Hermès, IL. <i>24, 343 ;</i> OD. <i>5, 47 ;</i><br><b>      9</b> hampe de javelot, XÉN. <i>Cyn. 10, 3 et 16</i> :<br><b>      10</b> <i>au pl</i>. faisceau de verges des licteurs romains, PLUT. <i>Popl. 10, Luc. 36</i> :<br><b>      11</b> houlette de berger, SPT. <i>Mich. 7, 14</i> :<br><b>      12</b> bâton, NT. <i>Matth. 10, 10, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> ligne, raie, IL. <i>12, 297 ; particul</i>. raie sur la peau d’un animal, ARSTT. <i>H.A. 4, 1, 25 ;</i> strie sur une pierre <i>ou</i> un métal, TH. <i>C.P. 4, 12, 6 ;</i><br><b>      2</b> ligne transversale qui raye l’horizon lorsque la pluie tombe au loin <i>ou</i> que le soleil pompe l’humidité du sol, ARSTT. <i>Meteor. 3, 2, 6 ; 3, 6, 3 ; Mund. 4, 22 ;</i> TH. <i>Sign. 1, 11 ;</i> PLUT. ;<br><b>      3</b> ligne d’écriture <i>ou</i> vers, SCH.-PD. <i>I. 3, 63 ;</i><br><b>      4</b> signe critique, raie en regard de certains passages, SCHOL. <i>cf</i>. ὀϐελός.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραβδος - ῥάβδος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (4)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4465":"<h1>rhabdouchos</h1>\n<p>Strong n° 4465 <i>Prononciation [hrab-doo'-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>quelqu'un qui porte les verges c.à.d. les faisceaux</li>\n<li>un licteur, officier public, qui porte les faisceaux bâton, et autres insignes de fonction devant un magistrat</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥαϐδοῦχος, ου (ὁ, ἡ)</b> <i>litt</i>. « qui porte une baguette », <i>d’où :</i><br><b>   I</b> <i>à Olympie :</i><br><b>      1</b> juge des jeux gymniques, PLAT. <i>Prot. 338</i> a ;<br><b>      2</b> sorte d’huissier de certains magistrats, THC. <i>5, 50 ;</i> AR. <i>Pax 734 ;</i><br><b>   II</b> <i>à Rome,</i> licteur, POL. <i>5, 26, 10, etc. ; Fr. gr. 116 ;</i> DH. <i>1, 502, 570 Reiske ;</i> DS. <i>5, 40 ; 17, 77 ;</i><br><b>   III</b> <i>à Syracuse, au plur., femmes de l’escorte d’Œnanthè, mère d’Agathocle,</i> POL. <i>15, 27, 13</i>.<br><span><b>Étym</b>. ῥάϐδος, ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραβδουχος - ῥαβδοῦχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4466":"<h1>Rhagau</h1>\n<p>Strong n° 4466 <i>Prononciation [hrag-ow']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ragau (Rehu) = « associé, ami »\n<ol><li>un des ancêtres de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ραγαυ</font> &lt; רעו - <font face=\"Georgia\">Ῥαγαύ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4467":"<h1>rhadiourgema</h1>\n<p>Strong n° 4467 <i>Prononciation [hrad-ee-oorg'-ay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une action de friponnerie, de coquin, une vilenie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥᾳδιούργημα, ατος (τὸ)</b> <span>[ῥᾱ]</span> action légère, inconsidérée, DH. <i>1, 77 ;</i> PLUT. <i>Pyrrh. 6, etc</i>.<br><span><b>Étym</b>. ῥᾳδιουργέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραδιουργημα - ῥᾳδιούργημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4468":"<h1>rhadiourgia</h1>\n<p>Strong n° 4468 <i>Prononciation [hrad-ee-oorg-ee'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aise dans l'action, faculté</li>\n<li>légèreté ou facilité dans la pensée ou l'action\n<ol type=\"a\">\n<li>amour d'une vie paresseuse et efféminée</li>\n</ol>\n</li>\n<li>manque de scrupule, ruse, malice, fraude, mauvaise conduite</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥᾳδιουργία, ας (ἡ)</b> <span>[ῥᾱ]</span><br><b>   I</b> facilité à faire qqe ch., XÉN. <i>Cyr. 1, 6, 34 ;</i><br><b>   II</b> légèreté, insouciance, indolence, XÉN. <i>Cyr. 7, 5, 74 etc. ; p. suite,</i> absence de scrupules, manque de conscience, POL. <i>12, 10, 5 ; d’où</i> mollesse, XÉN. <i>Mem. 2, 1, 20 ;</i> fraude, tromperie, PLUT. <i>Cato mi. 16</i>.<br><span><b>Étym</b>. ῥᾳδιουργός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραδιουργια - ῥᾳδιουργία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4469":"<h1>rhaka</h1>\n<p>Strong n° 4469 <i>Prononciation [rhak-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Raca = « vaurien »\n<ol>\n<li>vide, indigne, vaurien...</li>\n<li>expression de mépris utilisée parmi les Juifs au temps de Christ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρακα</font> &lt; ריק - <font face=\"Georgia\">ῥακά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4470":"<h1>rhakos</h1>\n<p>Strong n° 4470 <i>Prononciation [hrak'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un morceau déchiré</li>\n<li>un morceau de tissu</li>\n<li>étoffe</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥάκος, εος-ους (τὸ)</b> <span>[ᾰ]</span> déchirure, <i>d’où :</i><br><b>      1</b> morceau d’étoffe déchiré, haillon, loque, OD. <i>6, 178 ; 13, 434 ; 14, 342, 349 ;</i> AR. <i>Pl. 540, etc., au plur</i>. OD. <i>14, 512 ; 18, 67 et 74 ; 19, 507, etc. ;</i> HDT. <i>3, 129 ;</i> SOPH. <i>Ph. 39, 274 ; en gén</i>. morceau d’étoffe, lambeau, HDT. <i>7, 76 ; p. anal</i>. lambeau de chair, ESCHL. <i>Pr. 1023 ; p. ext</i>. linge, HPC. <i>472, 30, etc. ;</i><br><b>      2</b> <i>p. ext</i>. débris, ruines (d’une maison) ANON. (ARSTT. <i>Rhet. 3, 11, 13) ; fig. en parl. de pers</i>. ANTH. <i>9, 242, etc. ;</i> LUC. <i>Tim. 32 ;</i><br><b>      3</b> ride, AR. <i>Pl. 1065</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρακος - ῥάκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4471":"<h1>Rhama</h1>\n<p>Strong n° 4471 <i>Prononciation [hram-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rama (Ramah) = « une colline, hauteur »\n<ol><li>une ville de la tribu de Benjamin, située à environ 8 km au nord de Jérusalem sur la route de Béthel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ραμα</font> &lt; רמה - <font face=\"Georgia\">Ῥαμά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4472":"<h1>rhantizo</h1>\n<p>Strong n° 4472 <i>Prononciation [hran-tid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>asperger</li>\n<li>purifier par aspersion, de là purifier, nettoyer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥαντίζω<br>      1</b> asperger, NT. <i>Hebr. 9, 13, 19, 21 ; au pass</i>. ATH. <i>521</i> a ; SPT. <i>Lev. 6, 27, etc. ;</i><br><b>      2</b> <i>p. suite,</i> purifier, SPT. <i>Ps. 51, 7 ;</i> NT. <i>Hebr. 10, 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass</i>. ῥεράντισμαι, NT. <i>l. c</i>.<br><span><b>Étym</b>. ῥαντός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραντιζω - ῥαντίζω</font>\n<br><br>vient d'un dérivé de rhaino (asperger)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (4)</li>\n</ul>\n</td></tr>\n</table>","G4473":"<h1>rhantismos</h1>\n<p>Strong n° 4473 <i>Prononciation [hran-tis-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une aspersion (purification)\n<ol type=\"a\">\n<li>sang d'aspersion\n<ol>\n<li>c.à.d. désigné pour l'aspersion (servant à purifier)</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥαντισμός, οῦ (ὁ)</b> aspersion, SPT. <i>Num. 19, 9 ;</i> NT. <i>Hebr. 12, 24 ; 1Petr. 1, 2</i>.<br><span><b>Étym</b>. ῥαντίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραντισμος - ῥαντισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4474":"<h1>rhapizo</h1>\n<p>Strong n° 4474 <i>Prononciation [hrap-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>frapper avec une verge ou un bâton</li>\n<li>frapper à la face avec la paume de la main, souffleter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥαπίζω</b> <span>[ᾰ]</span> <span>(<i>impf</i>. ἐρράπιζον, <i>f</i>. ῥαπίσω, <i>ao</i>. ἐρράπισα, <i>pf. inus. ; pass. ao</i>. ἐρραπίσθην, <i>pf</i>. ῥεράπισμαι)</span><br><b>      1</b> frapper avec une baguette <i>ou</i> un bâton, <i>acc</i>. ANACR. <i>29, 2 ;</i> HDT. <i>7, 35, 223 ;</i> DÉM. <i>787, 23 ; au pass</i>. ANACR. <i>166 ;</i> HDT. <i>8, 59 ;</i><br><b>      2</b> <i>postér</i>. frapper <i>en gén., particul</i>. frapper à la figure, <i>au sens de l’att</i>. ἐπὶ κόρρης πατάξαι, PLUT. <i>M. 713</i> c ; A. TAT. <i>2, 24 ;</i> NT. <i>Matth. 5, 22 ; différ. de</i> κολαφίζειν, NT. <i>Matth. 26, 67 ;</i><br><b>      3</b> <i>p. ext</i>. battre (l’air) ARSTT. <i>An. 2, 8, 3 ; au pass</i>. ARSTT. <i>Meteor. 2, 8, 33, etc</i>.<br><span><b>Étym</b>. ῥαπίς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραπιζω - ῥαπίζω</font>\n<br><br>vient d'un dérivé du mot rhepo (laisser tomber, « coup »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G4475":"<h1>rhapisma</h1>\n<p>Strong n° 4475 <i>Prononciation [hrap'-is-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un coup avec une verge ou un bâton ou un fléau</li>\n<li>un coup avec le plat de la main, une claque dans la figure, un soufflet</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥάπισμα, ατος (τὸ)</b> <span>[ρᾰ]</span> coup de baguette <i>ou</i> de verge, <i>p. ext</i>. coup, ANTIPH. (<i>Com. fr. 3, 126</i>) ; LUC. <i>D. mer. 8, 2 ;</i> ANTH. <i>5, 289</i>.<br><span><b>Étym</b>. ῥαπίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραπισμα - ῥάπισμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G4476":"<h1>rhaphis</h1>\n<p>Strong n° 4476 <i>Prononciation [hraf-ece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une aiguille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥαφίς, ίδος (ἡ)</b> <span>[ᾰῐδ]</span><br><b>      1</b> aiguille, poinçon, ARCHIPP. (<i>Com. fr. 2, 725</i>) ; ANTH. <i>11, 110 ;</i><br><b>      2</b> aiguille, <i>poisson de mer,</i> ARSTT. <i>fr. 278 ;</i> OPP. <i>H. 1, 172</i>.<br><span><b>Étym</b>. ῥάπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ραφις - ῥαφίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4477":"<h1>Rhachab</h1>\n<p>Strong n° 4477 <i>Prononciation [hrakh-ab']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rahab = « large, spacieux, tumultueux »\n<ol><li>une prostituée de Jéricho</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ραχαβ</font> &lt; רחב - <font face=\"Georgia\">Ῥαχάβ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4478":"<h1>Rhachel</h1>\n<p>Strong n° 4478 <i>Prononciation [hrakh-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rachel = « agnelle ou brebis »\n<ol><li>l'épouse de Jacob</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ραχηλ</font> &lt; רחל - <font face=\"Georgia\">Ῥαχήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4479":"<h1>Rhebekka</h1>\n<p>Strong n° 4479 <i>Prononciation [hreb-bek'-kah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rebecca (Rebekah) = « ensorcelante, qui prend au piège »\n<ol><li>l'épouse d'Isaac</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρεβεκκα</font> &lt; רבקה - <font face=\"Georgia\">Ῥεβέκκα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4480":"<h1>rheda</h1>\n<p>Strong n° 4480 <i>Prononciation [hred'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un char, un chariot, un type de véhicule ayant quatre roues</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥέδη, ης (ἡ)</b> = <i>lat</i>. rheda, sorte de chariot à quatre roues, NT. <i>Apoc. 18, 13</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρεδα - ῥέδη</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4481":"<h1>Rhemphan</h1>\n<p>Strong n° 4481 <i>Prononciation [hrem-fan']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Remphan = « le diminué (comme sans vie) »\n<ol><li>le nom d'une idole adorée secrètement par les Israélites dans le désert</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρεμφαν</font> &lt; רמפן - <font face=\"Georgia\">Ῥαιφάν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4482":"<h1>rheo</h1>\n<p>Strong n° 4482 <i>Prononciation [hreh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>couler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥέω</b> <span>(<i>les formes en -εη, -εο, -εω ne se contractent pas ; f</i>. ῥεύσομαι, <i>att</i>. ῥυήσομαι, <i>ao.1 rare en att</i>. ἔρρευσα, <i>ao.2</i> ἐρρύην, <i>pf</i>. ἐρρύηκα)</span><br><b>   I <i>intr</i>.<br>      1</b> couler, <i>en parl. d’un cours d’eau,</i> HDT. <i>2, 22 ; 8, 138 ;</i> THC. <i>2, 5, etc. ; d’un liquide quelconque (larmes,</i> OD. <i>19, 204, etc. ; sang,</i> IL. <i>17, 86 ;</i> EUR. <i>Ph. 1480, etc.) ; avec un dat. :</i> πηγὴ ῥέει ὕδατι, IL. <i>22, 149,</i> la source épanche de l’eau ; ῥέεν αἵματι γαῖα, IL. <i>8, 65,</i> la terre ruisselait de sang ; ἱδρῶτι ῥεόμενος, LUC. <i>D. mort. 14, 5,</i> ruisselant de sueur ; πόλις χρυσῷ ῥέουσα, EUR. <i>Tr. 995,</i> ville où l’or coule à flots ; <i>qqf. avec un acc. :</i> Ἱμέρα ῥείτω γάλα, THCR. <i>Idyl. 5, 124,</i> qu’Himère ruisselle de lait ; ποταμὸς οἶνον ῥέων, LUC. <i>V.H. 1, 7, etc</i>. fleuve roulant du vin dans ses flots ; <i>cf</i>. SCH.-AR. <i>Pl. 287 ; avec le gén. :</i> ῥ. αἵματος, HPC. <i>572,</i> laisser couler du sang ; <i>cf</i>. ARR. <i>An. 4, 7, 10 ; prov</i>. <span>ἄνω ῥεῖν</span>, couler en arrière, <i>pour parler de choses impossibles,</i> EUR. <i>Suppl. 520 ;</i> DÉM. <i>433, 23, etc. ; t. de méd</i>. avoir l’écoulement menstruel, LUC. <i>Lex. 19 ; en parl. des intestins,</i> couler, <i>càd</i>. avoir un flux de ventre, DS. <i>5, 41 ; p. anal. en parl. de choses fluides (air,</i> PLUT. <i>M. 954</i> e ; <i>vent,</i> PLUT. <i>Sert. 17 ; flamme,</i> PLUT. <i>Brut. 31, etc</i>.) ; τὸ δὲ πῦρ διατελεῖ ἀεὶ ῥέον ὥσπερ ποταμός, ARSTT. <i>Juv. 5, 470 a, 3,</i> le feu se répand sans cesse comme un fleuve ; <i>en parl. d’un volcan,</i> EL. (STOB. <i>Fl. 79, 38) ; en parl. de la parole :</i> τοῦ ἀπὸ γλώσσης μέλιτος γλυκίων ῥέεν αὐδή, IL. <i>1, 249,</i> la parole coulait de sa langue, plus douce que le miel ; <i>en parl. d’une foule :</i> ῥεῖ πολὺς ὅδε λεώς, ESCHL. <i>Sept. 80,</i> voici la foule qui s’approche comme un flot roulant ; Θρῄκιος ῥέων στρατός, EUR. <i>Rhes. 290,</i> l’armée thrace qui s’avance comme un torrent ;<br><b>      2</b> <i>fig</i>. s’élancer vers, se livrer <i>ou</i> s’adonner à : πρὸς τὰ μαθήματα ἐρρυηκέναι, PLAT. <i>Rsp. 485</i> d, s’être adonné à l’étude ; ἐπὶ ποιητικὴν ῥυῆναι, PLUT. <i>Cic. 2,</i> s’être adonné à la poésie ; <i>avec idée d’hostilité,</i> s’élancer contre, assaillir : ὅλος ἐρρύη πρὸς τὸν Ἀλκιϐιάδην, PLUT. <i>Alc. 21,</i> il se répandit en un accès de colère contre Alcibiade ; πολὺς ῥέων καθ' ὑμῶν, DÉM. <i>272, 20,</i> se répandant en invectives contre vous ;<br><b>      3</b> couler de, glisser de, tomber : ἐκ χειρῶν βέλεα ῥέον, IL. <i>12, 159,</i> les traits volaient de leurs mains ; <i>en parl. de poils qui tombent,</i> OD. <i>10, 393 ;</i> ARSTT. <i>H.A. 3, 11 ; de fruits mûrs qui se détachent,</i> POL. <i>12, 4, 14 ; cf</i>. HÉS. <i>fr. 42, 3 Göttling ;</i> THCR. <i>Idyl. 2, 89 ;</i><br><b>      4</b> s’écouler, passer : ἰόντων πάντων καὶ ἀεὶ ῥεόντων, PLAT. <i>Crat. 439</i> c, toutes choses passant et étant sans cesse emportées par le cours du temps ; <i>abs</i>. οἱ ῥέοντες, PLAT. <i>Theæt. 181</i> a, les philosophes de l’école d’Héraclite qui admettent que les choses sont en mouvement perpétuel, <i>p. opp. à</i> οἱ τοῦ ὅλου στασιῶται ; <i>fig</i>. s’écouler, se perdre, se corrompre : εἰ ῥέοι τὸ σῶμα καὶ ἀπολλύοιτο ἔτι ζῶντος τοῦ ἀνθρώπου, PLAT. <i>Phæd. 87</i> d, si le corps se gâtait et périssait quand l’homme est encore vivant ;<br><b>   II <i>tr.</i></b> faire couler, verser, ARCHIL. <i>17 ;</i> DÉM. <i>Lept. 273 ; d’où subst</i>. τὰ ῥέοντα, <i>v</i>. ῥέον ;<br><b><i>Moy.</i></b> (<i>prés</i>. ῥέομαι, PLUT. <i>Cor. 3 ;</i> LUC. <i>D. mort. 14, 5, etc. ; impf. 3 sg</i>. ἐρρεῖτο, EUR. <i>Hel. 1618) m. sign</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. comme dans les écriv. att. la contract. n’a lieu que dans les formes en</i> -εε- = ει ; <i>v. Meisterh. p. 140, 5. Act. prés. ind. 3 sg. poét</i>. ῥέει, IL. <i>22, 149 ; 3 pl. dor</i>. ῥέοντι, THCR. <i>Idyl. 14, 38. Dans une inscr. att. part. prés. fém. ῥείουσα, à côté de</i> ῥέουσα, CIA. <i>2, 681, 22 (après 400 av. J.C.), v. Meisterh. p. 36, 4. Impf. 3 sg</i>. ἔρρει, IL. <i>17, 86 ;</i> EUR. <i>Hec. 528 ; ou</i> ῥέε, OD. <i>19, 204, etc. ;</i> ῥέεν, IL. <i>1, 249. Fut. réc</i>. ῥευσοῦμαι, ARSTT. <i>Meteor. 2, 2, 23 ; 2, 4, 20 ;</i> ῥεύσω, ANTH. <i>5, 125 ;</i> SIB. <i>3, 84 ;</i> GEOP. <i>9, 12. Ao.2, 3 sg. épq</i>. ῥύη, OD. <i>3, 455. Pf. réc</i>. ἔρρυκα, GAL. <i>5, 398. Moy. prés. part. poét</i>. ῥεούμενος, ORACL. (HDT. <i>7, 140</i>).<br><span><b>Étym</b>. <i>p</i>. *ῥέϝω, <i>de la R. indo-europ</i>. *sreu-, couler ; <i>cf. sscr</i>. srávati, <i>angl</i>. stream.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρεω - ῥέω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4483":"<h1>rheo</h1>\n<p>Strong n° 4483 <i>Prononciation [hreh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>verser, prononcer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>*ῥέω</b>, <i>p</i>. *ϝρέω, *ϝέρω, dire, <i>seul. aux temps suiv. : <span>act. pf</span></i>. εἴρηκα ; <i>pass. f</i>. ῥηθήσομαι, <i>ao</i>. ἐρρήθην <i>et</i> ἐρρέθην, <i>pf</i>. εἴρημαι, <i>pl.q.pf</i>. εἰρήμην, <i>f. ant</i>. εἰρήσομαι. <i>Pass. ao. ion</i>. εἰρέθην, HDT. <i>4, 77, etc. Pf. 3 pl. ion</i>. εἰρέαται, HDT. <i>7, 96</i>.<br><span><b>Étym</b>. <i>cf</i>. εἴρω², εἴρηκα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρεω - ῥέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n25 fois dans 25 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (20)</li>\n<li>Romains (2)</li>\n<li>Galates (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4484":"<h1>Rhegion</h1>\n<p>Strong n° 4484 <i>Prononciation [hrayg'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Reggio (Angl. Rhegium) = « brèche »\n<ol><li>une ville Italienne située à l'entée sud du détroit de Messine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ῥήγιον, ου (τὸ)</b> = <i>lat</i>. Rhegium (<i>auj</i>. Reggio di Calabria) <i>v. et prom. au S. de l’Italie,</i> HDT. <i>1, 161, etc. ;</i> THC. <i>3, 86, etc</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ Ῥήγιον, PLUT. <i>Tim. 11</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρηγιον - Ῥήγιον</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4485":"<h1>rhegma</h1>\n<p>Strong n° 4485 <i>Prononciation [hrayg'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui a été brisé ou mis en morceaux\n<ol type=\"a\">\n<li>une fracture, une brèche, une fente</li>\n<li>chute, ruine</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥῆγμα, ατος (τὸ)</b> rupture, <i>d’où :</i><br><b>      1</b> fracture, <i>joint à</i> στρέμμα, DÉM. <i>24, 6 ; 156, 1, etc. ;</i><br><b>      2</b> déchirure, ARSTT. <i>H.A. 10, 2, 5 ; particul</i>. déchirure d’un vêtement, ARCHIPP. (<i>Com. fr. 2, 725</i>) ; déchirure du sol, ARSTT. <i>H.A. 9, 41, 16 ;</i> brèche dans un mur, POL. <i>13, 6, 8 ;</i><br><b>      3</b> abcès, HPC. <i>479, 55</i>.<br><span><b>Étym</b>. ῥήγνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρηγμα - ῥῆγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4486":"<h1>rhegnumi</h1>\n<p>Strong n° 4486 <i>Prononciation [hrayg'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>déchirer, éclater ou rompre en morceaux, rompre\n<ol type=\"a\">\n<li>déchirer en pièces</li>\n<li>éclater\n<ol>\n<li>de joie, d'enfants ou de muets commençant à parler</li>\n</ol>\n</li>\n<li>déformer, convulser\n<ol>\n<li>d'un démon donnant des convulsions à un homme possédé</li>\n<li>jeter à terre, lancer au sol (fréquent dans les cas de possession par un démon et d'épilepsie)</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥήγνυμι</b> <span>(<i>f</i>. ῥήξω, <i>ao</i>. ἔρρηξα, <i>pf.1 récent</i> ἔρρηχα, <i>pf.2 au sens intr</i>. ἔρρωγα ; <i>pass. ao.2</i> ἐρράγην, <i>pf. inus</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> briser, rompre : τεῖχος, IL. <i>12, 198,</i> renverser un mur ; πύλας, IL. <i>12, 291 ;</i> θύρας, IL. <i>9, 475,</i> briser des portes ; θώρηκας, IL. <i>2, 544,</i> briser des cuirasses ; ὀστέον, IL. <i>12, 185,</i> briser un os ; χρόα, IL. <i>23, 673,</i> déchirer la peau ; πέπλους, ESCHL. <i>Pers. 199,</i> déchirer ses vêtements ; δώματα χαμᾶζε, EUR. <i>Bacch. 633,</i> jeter des maisons à terre ; γῆς δάπεδον, AR. <i>Pl. 515,</i> déchirer le sol de la terre (avec la charrue) ; ἕλκος, PD. <i>N. 8, 50,</i> faire une blessure en déchirant ; φάλαγγα, IL. <i>6, 6,</i> rompre une troupe alignée ; στίχας ἀνδρῶν, IL. <i>15, 615,</i> rompre les rangs ennemis, passer à travers ; <i>au pass. :</i> κῦμα χέρσῳ ῥηγνύμενον, IL. <i>4, 425,</i> flot qui se brise contre la terre ferme ; ῥήγνυται τὸ τεῖχος, XÉN. <i>Hell. 5, 2, 5,</i> le mur crève ; ῥαγέντα ἱμάτια, XÉN. <i>Cyr. 1, 6, 16,</i> vêtements déchirés ; <i>fig</i>. ῥαγεῖσαι ἐλπίδες, ESCHL. <i>Ag. 505,</i> espérances brisées ;<br><b>      2</b> <i>p. suite,</i> faire éclater, faire jaillir : ῥ. πηγὰς ναμάτων θερμῶν, PLUT. <i>Mar. 19,</i> faire jaillir des sources d’eaux chaudes ; ῥ. φωνήν, déchirer, <i>càd</i>. faire éclater la voix, <i>en parl. des muets ou des enfants qui commencent à parler,</i> HDT. <i>1, 85 ; 2, 2 ; ou de pers. assourdies ou étonnées qui font de nouveau entendre un son,</i> HPC. <i>1155</i> c ; <i>ou simpl</i>. rompre le silence, élever la voix (<i>cf. lat</i>. rumpere vocem, VIRG. <i>Æn. 2, 129 ; 9, 377</i>) ; HDT. <i>5, 93 ;</i> DÉM. <i>126, 26 ;</i> ῥ. φωνήν τινι, AR. <i>Nub. 356, 960,</i> élever la voix pour s’adresser à qqn ; ῥῆξαι αὐδήν, EUR. <i>Suppl. 710, m. sign. ; abs</i>. ῥῆξον, SPT. <i>Esaï. 54, 1,</i> élève la voix ; <i>de même</i> ῥ. κλαυθμόν, PLUT. <i>Per. 36,</i> éclater en pleurs ; ῥ. δακρύων νάματα, SOPH. <i>Tr. 919,</i> fondre en larmes ; <i>au pass</i>. ῥήγνυνται πηγαί, PLUT. <i>Pel. 16,</i> des sources jaillissent ; βροντὴ ἐρράγη, SOPH. <i>fr. 507 Dind.,</i> le tonnerre éclata ;<br><b>   II</b> <i>intr. (surt. au pf.2</i> ἔρρωγα, <i>rar. au prés</i>.) éclater, jaillir : ἔρρωγεν παγὰ δακρύων, SOPH. <i>Tr. 852,</i> une source de larmes a jailli ; <i>fig</i>. ἔρρωγεν κακά, SOPH. <i>O.R. 1280 ;</i> EUR. <i>Hipp. 1338,</i> des maux ont éclaté ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. ῥήξομαι, <i>ao</i>. ἐρρηξάμην)</span><br><b>      1</b> briser, rompre pour se frayer un passage : τεῖχος, IL. <i>12, 440,</i> un mur ; φάλαγγας, IL. <i>11, 90, etc. ;</i> στίχας, IL. <i>15, 409 ;</i> rompre les rangs ennemis ; <i>abs</i>. IL. <i>12, 411 ;</i><br><b>      2</b> faire éclater : φωνήν, ANTH. <i>5, 222,</i> faire éclater sa voix, élever sa voix ; ἔριδα, IL. <i>20, 55,</i> faire éclater une lutte, un combat.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. itér. 3 sg</i>. ῥήγνυσκε, IL. <i>7, 141. Ao. poét</i>. ῥῆξα, IL. <i>12, 185 ;</i> PD. <i>N. 8, 29. Moy. impf. poét</i>. ῥηγνύμην, IL. <i>13, 718 ; 3 pl. épq</i>. ῥηγνύατο, ARAT. <i>817. Ao. épq</i>. ῥηξάμην, IL. <i>11, 90 ; sbj. 1 pl. épq</i>. ῥηξόμεθα, IL. <i>12, 224</i>.<br><span><b>Étym</b>. <i>p</i>. *ϝρήγνυμι, <i>de la R. indo-europ</i>. *ureh₁ǵ-, briser ; <i>cf</i>. ῥηγμίν, ῥήσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρηγνυμι - ῥήγνυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4487":"<h1>rhema</h1>\n<p>Strong n° 4487 <i>Prononciation [hray'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est ou a été émis par une voix humaine, la chose dite, la parole\n<ol type=\"a\">\n<li>tout son produit par la voix et ayant un sens défini</li>\n<li>parole, discours\n<ol>\n<li>ce que quelqu'un a dit</li>\n</ol>\n</li>\n<li>une série de mots joints ensemble dans une phrase (une déclaration de l'esprit faite dans des mots)\n<ol>\n<li>une émission</li>\n<li>un dire de toute sorte comme un message, un récit</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>le sujet matière du discours, la chose dont il est parlé\n<ol type=\"a\">\n<li>que ce soit un récit</li>\n<li>que ce soit un ordre ou un commandement</li>\n<li>un sujet de dispute, un cas de loi</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥῆμα, ατος (τὸ) :<br>   I</b> tout ce qu’on dit :<br><b>      1</b> mot, parole, HDT. <i>7, 162 ; 8, 83 ;</i> AR. <i>Ran. 821, Pax 521 ;</i> PLAT. <i>Prot. 343</i> b, <i>etc. ; p. opp. à</i> δόγμα, PLAT. <i>Rsp. 464</i> e ; <i>à</i> ἔργματα, (<i>actions</i>) PD. <i>N. 4, 10 ; à</i> ἔργον, SOPH. <i>O.C. 873 ;</i> THC. <i>5, 111 ; à</i> τὸ ἀληθές, PLAT. <i>Phæd. 102</i> b ; κατὰ ῥῆμα, ESCHN. <i>44, 16,</i> mot pour mot ;<br><b>      2</b> langage, discours, poème, THGN. <i>1148 ;</i> PD. <i>P. 4, 493 ;</i> HDT. <i>8, 83 ;</i> ATT. ;<br><b>      3</b> phrase, <i>p. opp. à</i> ὄνομα (<i>mot</i>) PLAT. <i>Crat. 399</i> b ; <i>au plur</i>. PLAT. <i>Leg. 840</i> c ;<br><b>      4</b> objet d’un discours, sujet de controverse <i>ou</i> de discours, NT. <i>Luc. 1, 37 et 65 ; 2, 15 ;</i><br><b>   II</b> <i>t. de gr</i>. le verbe, <i>p. opp. à</i> ὄνομα (<i>le nom</i>) PLAT. <i>Soph. 262</i> a, <i>etc. ;</i> ARSTT. <i>Poet. 20, 9, etc. ; particul. chez les Stoïc. en parl. de l’infinitif, p. opp. aux autres modes appelés</i> συμϐάματα <i>ou</i> κατηγορήματα, SEXT. <i>629, 17 Bkk. ;</i> DL. <i>4, 31 ; 7, 58 ;</i><br><b>   III</b> <i>p. ext</i>. chose, <i>en gén., hébraïsme,</i> SPT. <i>Gen. 15, 1 ; 18, 14 ;</i> NT. <i>Luc. 3, 15 ; au plur</i>. actions, actes, SPT. <i>3Reg. 11, 41</i>.<br><span><b>Étym</b>. εἴρω².</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρημα</font> &lt; דבר - <font face=\"Georgia\">ῥῆμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n69 fois dans 66 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (2)</li>\n<li>Luc (18)</li>\n<li>Jean (12)</li>\n<li>Actes (14)</li>\n<li>Romains (4)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (2)</li>\n<li>Hébreux (4)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4488":"<h1>Rhesa</h1>\n<p>Strong n° 4488 <i>Prononciation [hray-sah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rhésa (Angl. Rhesa) = « tête »\n<ol><li>le fils de Zorobabel dans la généalogie de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρεσα</font> &lt; רישא - <font face=\"Georgia\">Ῥησά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4489":"<h1>rhetor</h1>\n<p>Strong n° 4489 <i>Prononciation [hray'-tore]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un orateur, celui qui fait des discours\n<ol type=\"a\">\n<li>d'un orateur judiciaire ou avocat</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥήτωρ, ορος (ὁ, ἡ) :<br>      1</b> orateur, EUR. <i>Hec. 126 ; particul. à Athènes,</i> orateur public dans l’assemblée, THC. <i>8, 1 ;</i> AR. <i>Ach. 38, 60, etc. ; Att. ; abs</i>., ὁ ῥ. l’orateur par excellence, <i>càd</i>. Démosthène, PLUT. <i>M. 350</i> c, <i>etc. ;</i><br><b>      2</b> maître d’éloquence, rhéteur, PLUT. <i>M. 131</i> a ; <i>en mauv. part,</i> ISOCR. <i>185</i> b ;<br><b>      3</b> celui qui prononce une sentence, juge, SOPH. <i>fr. 937 Dind</i>.<br>ἡ ῥήτωρ, AR. <i>fr. 673 Dind</i>.<br><span><b>Étym</b>. εἴρω².</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρητωρ - ῥήτωρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4490":"<h1>rhetos</h1>\n<p>Strong n° 4490 <i>Prononciation [hray-toce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>expressément, dans des paroles formelles, explicitement, littéralement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥητῶς</b>, <i>adv</i>., en termes exprès <i>ou</i> formels, expressément, POL. <i>3, 23, 5</i>.<br><span>•<i> Cp</i>. ῥητότερον, CLÉM. <i>1, 1317 b Migne</i>. <i>• Sup</i>. ῥητότατα, SEXT. <i>7, 16</i>.<br><span><b>Étym</b>. ῥητός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρητως - ῥητῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4491":"<h1>rhiza</h1>\n<p>Strong n° 4491 <i>Prononciation [hrid'-zah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>métaph. descendant, progéniture</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥίζα, ης (ἡ)</b> racine :<br><b>   I</b> <i>au propr</i>. OD. <i>10, 304 ; 23, 196 ;</i> ATT. ; <i>particul</i>. racine médicinale, IL. <i>11, 846 ; au plur</i>. IL. <i>9, 542 ; 12, 134 ;</i> OD. <i>12, 435, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> racine d’une ch. (<i>de l’œil,</i> OD. <i>9, 390 ;</i> EUR. <i>H.f. 933 ; des cheveux,</i> PLAT. <i>Phædr. 251</i> b ; ARSTT. <i>H.A. 3, 11, 12 ; des dents,</i> ARSTT. <i>G.A. 5, 8, 9 ; du ventre, càd</i>. le nombril, ARSTT. <i>H.A. 1, 13, 1, etc</i>.) ; pied d’une montagne, ESCHL. <i>Pr. 365 ;</i> POL. <i>2, 66, 10 ;</i> PLUT. <i>Syll. 16 ;</i> fondement de la terre, HÉS. <i>O. 19 ;</i> ESCHL. <i>Pr. 1047 ; joint à</i> ἀρχαί, ARSTT. <i>Meteor. 2, 1, 2, etc. ;</i> fondement de toutes choses, <i>joint à</i> βάσις, T. LOCR. <i>97</i> e ;<br><b>      2</b> souche d’une famille, PD. <i>O. 2, 83, etc. ;</i> ESCHL. <i>Ag. 966,;</i> SOPH. <i>Aj. 1178, etc. ; d’où</i> race, famille, ESCHL. <i>Sept. 755 ;</i> EUR. <i>I.T. 610, etc. ; joint à</i> σπέρμα, DÉM. <i>784, 28 ;</i><br><b>      3</b> source <i>ou</i> origine d’une ch. (<i>du bien, du mal, etc</i>.) EUR. <i>fr. inc. 904, 11 Nauck ;</i> PLUT. <i>M. 4</i> b, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Acc</i>. ῥίζην, <i>p</i>. ῥίζαν, <i>par nécess. prosod</i>. M. SID. <i>89</i>.<br><span><b>Étym</b>. <i>p</i>. *ϝρίδ-ϳα ; <i>étymol. incert., cf</i>. ῥάδιξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ριζα - ῥίζα</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 16 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Luc (2)</li>\n<li>Romains (5)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4492":"<h1>rhizoo</h1>\n<p>Strong n° 4492 <i>Prononciation [hrid-zo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>renforcé par des racines, rendre ferme, fixer, établir, faire qu'une personne ou une chose soit complètement enracinée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥιζόω-ῶ</b> <span>(<i>ao</i>. ἐρρίζωσα, <i>pf. pass</i>. ἐρρίζωμαι)</span><br><b>      1</b> faire prendre racine, enraciner, TH. <i>C.P. 2, 4, 1, au pass</i>. prendre racine ; s’enraciner, XÉN. <i>Œc. 19, 9 ;</i> ARSTT. <i>H.A. 5, 15, 20 ;</i> TH. <i>C.P. 1, 2, 1 ; fig</i>. faire prendre racine, enraciner (la tyrannie, <i>etc.) acc</i>. HDT. <i>1, 64 ; d’où au pass</i>. s’enraciner, HDT. <i>1, 60 ;</i> PLAT. <i>Leg. 839</i> a ; <i>p. suite,</i> fixer solidement, <i>acc</i>. OD. <i>13, 163 ;</i><br><b>      2</b> couvrir de plantations, <i>d’où au pass</i>. être couvert de plantations, être planté d’arbres, OD. <i>7, 122 ;</i><br><b><i>Moy.</i></b> prendre racine, TH. <i>H.P. 2, 5, 6</i>.<br><span><b>Étym</b>. ῥίζα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ριζοω - ῥιζόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4493":"<h1>rhipe</h1>\n<p>Strong n° 4493 <i>Prononciation [hree-pay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un jet, un coup, un battement, un clin d'œil</li>\n<li>un court instant de temps</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥιπή, ῆς (ἡ)</b> <span>[ῑ]</span><br><b>   I</b> jet, <i>càd. :</i><br><b>      1</b> <i>act</i>. action de jeter, de lancer : βελέων, PD. <i>N. 1, 102,</i> des traits ; ποδῶν, EUR. <i>I.T. 885,</i> action de lancer le pied en avant, marche ; ὀφθαλμοῦ, NT. <i>1Cor. 15, 52,</i> action de jeter un regard, coup d’œil ;<br><b>      2</b> <i>au sens réfléchi,</i> action de se lancer, force d’impulsion (<i>d’une javeline,</i> IL. <i>16, 589 ; d’une pierre,</i> IL. <i>12, 462 ;</i> OD. <i>8, 192, etc</i>.) ; Βορέαο, IL. <i>15, 171 ; 19, 358,</i> souffle impétueux de Borée ; πυρός, IL. <i>21, 12,</i> jet de feu ; ἀνδρός, IL. <i>8, 355,</i> course impétueuse d’un guerrier ; <i>fig</i>. Ἀφροδίτης, OPP. <i>H. 4, 141,</i> transports causés par Aphrodite ; <i>p. suite,</i> émanation : οἴνου, PD. <i>fr. 147,</i> odeur qu’exhale le vin ; ἄστρων, SOPH. <i>El. 106,</i> rayonnement des astres ;<br><b>   II</b> <i>p. ext</i>. aile, A. RH. <i>2, 935</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ῥιπά, PD. <i>l. c</i>.<br><span><b>Étym</b>. ῥίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ριπη - ῥιπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4494":"<h1>rhipizo</h1>\n<p>Strong n° 4494 <i>Prononciation [hrip-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre de l'air en mouvement, soit dans le but d'allumer un feu ou pour se rafraîchir\n<ol type=\"a\">\n<li>souffler sur un feu</li>\n<li>ventiler, c.à.d. rafraîchir avec un ventilateur</li>\n</ol>\n</li>\n<li>ballotter ici et là, agiter\n<ol type=\"a\">\n<li>du vent</li>\n<li>personnes dont l'esprit est ballotté entre espérance et crainte, entre faire ou ne pas faire une chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥιπίζω</b> <span>[ρῑ]</span><br><b>      1</b> éventer, ventiler, HPC. <i>V. med. 14 ;</i> MOSCHION <i>Mul. pass. 136 ; au pass</i>. être ventilé, ANTIPH. (<i>Com. fr. 3, 117</i>) ;<br><b>      2</b> agiter, <i>en parl. du vent ; d’où au pass</i>. être agité par le vent, ARSTT. <i>Probl. 38, 6 ;</i> PHIL. <i>2, 511 ; particul</i>. être soulevé par le vent, NT. <i>Jac. 1, 6 ;</i><br><b>      3</b> souffler pour attiser (le feu, <i>etc.) acc</i>. PLUT. <i>Flam. 21 ;</i> ANTH. <i>5, 122 ; fig</i>. agiter, exciter (une guerre, une querelle) <i>acc</i>. HOM. <i>fr. 16 ;</i> AR. <i>Ran. 360 ; au pass. fig</i>. être excité (par l’espérance) ALCIPHR. <i>3, 47</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. part. poét</i>. ῥιπίσσας, HOM. <i>fr. 16</i>.<br><span><b>Étym</b>. ῥιπίς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ριπιζω - ῥιπίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4495":"<h1>rhipteo</h1>\n<p>Strong n° 4495 <i>Prononciation [hrip-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter</li>\n<li>jeter à terre</li>\n<li>jeter en avant ou devant</li>\n<li>poser (avec la suggestion de hâte et de manque de soin)</li>\n<li>se jeter au sol, se prosterner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥιπτέω-ῶ</b> (<i>seul. prés. et impf.) c</i>. ῥίπτω, HDT. <i>4, 188 ; 7, 50, etc. ;</i> SOPH. <i>Ant. 131, Aj. 239 ;</i> THC. <i>4, 95 ;</i> EUR. <i>Her. 150 ;</i> PLAT. <i>Tim. 80</i> a, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 3 pl. ion</i>. ῥιπτεῦσι, HDT. <i>4, 94 ; impf. ion</i>. ἐρρίπτεον, HDT. <i>8, 53</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ριπτεω - ῥιπτέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4496":"<h1>rhipto</h1>\n<p>Strong n° 4496 <i>Prononciation [hrip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter, lancer</li>\n<li>jeter à terre</li>\n<li>jeter devant</li>\n<li>poser (avec la suggestion de hâte et de manque de soin)</li>\n<li>se jeter au sol, se prosterner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥίπτω</b> <span>(<i>impf</i>. ἔρριπτον, <i>f</i>. ῥίψω, <i>ao</i>. ἔρριψα, <i>pf</i>. ἔρριφα <span>[ῑ]</span>; <i>pass. f. 2</i> ῥιφήσομαι, <i>ao</i>. ἐρρίφθην, <i>ao.2</i> ἐρρίφην <span>[ῐ]</span>, <i>pf</i>. ἔρριμμαι, <i>pl.q.pf</i>. ἐρρίμμην, <i>f. ant</i>. ἐρρίψομαι)</span><br><b>   I <i>tr. :</i><br>      1</b> jeter, lancer : δίσκον, IL. <i>23, 842,</i> le disque ; κεραυνόν, PD. <i>P. 3, 101 ;</i> βέλη, PLAT. <i>Leg. 795</i> c ; λίθον, ARSTT. <i>Nic. 2, 1,</i> lancer la foudre, des traits, une pierre ; ῥ. τινὰ ἀπὸ βηλοῦ, IL. <i>15, 23 ;</i> ἀπὸ πύργου, IL. <i>24, 735,</i> lancer qqn du haut du ciel, d’une tour ; ῥ. τι ἀπὸ ἕο, OD. <i>9, 398,</i> lancer qqe ch. loin de soi ; ῥ. τινὰ ἐς Τάρταρον, IL. <i>8, 13 ;</i> ESCHL. <i>Pr. 1051 ;</i> PLAT. <i>Phæd. 113</i> e, jeter qqn dans le Tartare ; ῥ. τι πρός τι, OD. <i>11, 592 ;</i> ESCHL. <i>Pr. 992,</i> jeter une chose contre une autre ; ῥ. τι ἐπί τινι, ESCHL. <i>Pr. 1043 ;</i> ἐπί τινα, LUC. <i>Conv. 44,</i> jeter qqe ch. sur qqn ; ῥ. ὠλένας εἰς οὐρανόν, EUR. <i>Hel. 1096,</i> lever vivement les bras vers le ciel ; πέτρον ῥ. τινός, EUR. <i>Bacch. 1095,</i> lancer une pierre sur qqn ; ῥ. τινὰ πρὸς πέτραν, SOPH. <i>Tr. 780,</i> lancer qqn contre un rocher ; τινὰ κατὰ πέτρας, EUR. <i>I.T. 1430 ;</i> ἀπὸ πέτρας, PLUT. <i>Rom. 18,</i> lancer qqn du haut d’un rocher ; ῥ. ἑαυτὸν ἀπὸ πέτρας, ESCHL. <i>Pr. 748 ;</i> κατὰ κρημνῶν, THC. <i>7, 44, etc</i>. se jeter d’un rocher ; ῥ. ἑαυτὸν χθονί, SOPH. <i>Tr. 789 ;</i> ῥ. εἰς τὴν θάλασσαν, HDT. <i>1, 24 ;</i> DÉM. <i>883, 27,</i> se jeter à terre, dans la mer ; εἰς τοὺς πολεμίους, DH. <i>5, 46,</i> se jeter au milieu de l’ennemi ; <i>abs</i>. ῥ. ἑαυτόν, se précipiter en bas, se donner la mort en se jetant en bas, XÉN. <i>Cyr. 3, 1, 25 ; en parl. de malades,</i> ῥ. ἑαυτόν, se jeter de côté et d’autre dans l’agitation, HPC. <i>590, 9 ; fig</i>. ῥ. τινὰ ἐς τὸ δυστυχές, ESCHL. <i>Ch. 913,</i> précipiter qqn dans le malheur ; ῥ. ἑαυτὸν εἰς ἐλπίδας ἀπόρους, PLUT. <i>Them. 24,</i> se laisser aller à des espérances sans issue ; ῥ. λόγους τραχεῖς, ESCHL. <i>Pr. 312,</i> lancer, proférer des paroles rudes ; ῥ. νεανίας λόγους ἔς τινα, EUR. <i>Alc. 683,</i> lancer contre qqn des paroles téméraires (<i>litt</i>. de jeune homme) ; ῥ. ἀρὰς Ἀχαιοῖς, EUR. <i>Tr. 729,</i> lancer des imprécations contre les Grecs ;<br><b>      2</b> laisser tomber : ῥ. κλῆρον, PLAT. <i>Rsp. 617</i> c, laisser tomber, jeter le sort ; ῥ. τὸν πρὸς Ἀργείους Ἄρη, EUR. <i>Rhes. 446,</i> risquer la bataille contre les Argiens ; ῥ. κίνδυνον, EUR. <i>Ino fr. 406, 7,</i> courir un risque, s’exposer à un danger ;<br><b>      3</b> <i>p. anal</i>. rejeter : ῥ. τινὰ ἐκ γῆς, SOPH. <i>O.R. 1436,</i> rejeter qqn hors du pays, le bannir ; ῥ. ἑαυτὸν ἐκ χθονός, SOPH. <i>O.R. 1290,</i> s’exiler ;<br><b>      4</b> rejeter, abandonner, <i>acc</i>. SOPH. <i>Ph. 265 ; particul</i>. exposer un enfant, SOPH. <i>O.R. 719 ;</i> jeter, <i>en parl. de cadavres :</i> ῥ. δέμας κύνεσσιν, ANTH. <i>8, 213,</i> jeter un cadavre aux chiens ; <i>au pass</i>. SOPH. <i>Aj. 817 ; abs</i>. être abandonné, être gisant, POL. <i>5, 48, 2 ;</i> SPT. <i>1Macc. 9, 36 ;</i> PLUT. <i>Galb. 28 ;</i><br><b>      5</b> jeter, lancer au loin, se débarrasser de : τὰ ἱμάτια, PLAT. <i>Rsp. 474</i> a, rejeter ses vêtements ; τὰ ὅπλα, XÉN. <i>Cyr. 4, 2, 32 ;</i> PLAT. <i>Leg. 944</i> c, jeter ses armes ; τὴν ἀσπίδα, ESCHN. <i>117, 2,</i> jeter son bouclier ; <i>p. opp. à</i> ἀποϐεϐληκέναι, LYS. <i>117 ; avec idée de mépris ou de dédain,</i> SOPH. <i>Aj. 1271 ;</i><br><b>   II <i>intr.</i></b> se jeter, se précipiter, ἐς πόντον, THGN. <i>175 ;</i> εἰς τὴν θάλασσαν, XÉN. <i>Cyn. 9, 20,</i> dans la mer ; <i>fig</i>. ἐν πένθει EUR. <i>Hel. 1311,</i> s’abandonner à la douleur.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. itér</i>. ῥίπτασκον, IL. <i>15, 23 ;</i> HÉS. <i>Sc. 256 ;</i> ORPH. <i>fr. 16, 3, et</i> ῥίπτεσκον, NIC. <i>fr. 26. Ao. poét</i>. ἔριψα, ARION <i>18 Bgk ;</i> MOSCH. <i>3, 32 ; ou</i> ῥῖψα, IL. <i>3, 378 ;</i> HÉS. <i>Th. 868 ; 3 sg</i>. ἔριψεν, HH. <i>Merc. 79 ; part. dor</i>. ῥίψαις, PD. <i>P. 1, 45. Pf. 3 sg</i>. ἔρριφε <span>[ῐ]</span> OPP. <i>C. 4, 350. Pass. f. 2</i> ῥιφήσομαι, PLUT. <i>C. Gracch. 3. Ao.2 poét</i>. ἐρίφην <span>[ῐ]</span> ANTH. <i>12, 234. Pf. poét</i>. ῥέριμμαι, PD. <i>fr. 314 Bgk. Moy. ao. poét</i>. ῥιψάμην, MAN. <i>6, 10</i>.<br><span><b>Étym</b>. <i>inconnue ; rad</i>. *ϝριπ-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ριπτω - ῥίπτω</font>\n<br><br>un verbe primaire (peut-être parent de , à travers l'idée de mouvement soudain)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4497":"<h1>Rhoboam</h1>\n<p>Strong n° 4497 <i>Prononciation [hrob-o-am']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Roboam (Angl. Rehoboam) = « qui affranchit le peuple »\n<ol><li>le fils de Salomon par Naama, princesse Ammonite</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ροβοαμ</font> &lt; רחבעם - <font face=\"Georgia\">Ῥοβοάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G4498":"<h1>Rhode</h1>\n<p>Strong n° 4498 <i>Prononciation [hrod'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rhode (Angl. Rhoda) = « rose, ou rosier »\n<ol><li>nom d'une certaine servante de Marie, la mère de Jean-Marc</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥοδῆ</b>, <i>v</i>. ῥοδέα.<br><br>\n<b>ῥοδέα, ας</b>, <i>seul. par contr</i>. <b>ῥοδῆ, ῆς (ἡ)</b> buisson de roses, ARCHIL. <i>29 ;</i> TH. <i>H.P. 3, 18, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ῥοδέη, A. RH. <i>3, 1020</i>.<br><span><b>Étym</b>. ῥόδον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ροδη - Ῥόδη</font>\n<br><br>vient probablement de rhode (une rose)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4499":"<h1>Rhodos</h1>\n<p>Strong n° 4499 <i>Prononciation [hrod'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rhodes = « rosier »\n<ol><li>île bien connue de la Méditerranée, vis à vis de la côte de Carie, et dont Rhodes est la capitale</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ῥόδος, ου (ἡ)</b> Rhodos (Rhodes) :<br><b>      1</b> <i>î. dans la mer de Karpathos (auj</i>. Róđos) IL. <i>2, 654, 655 ;</i> PD. <i>O. 7, 104, etc. ;</i> ESCHL. <i>Pers. 891 ;</i> HDT. <i>1, 174, etc. ;</i> THC. <i>6, 4, etc. ;</i> XÉN. <i>Hell. 1, 1, 2, etc. ; avec une v. du même nom,</i> ANTH. <i>6, 171 ; App. 357 ;</i> A. PL. <i>82, etc. ;</i><br><b>      2</b> <i>nymphe,</i> PD. <i>O. 7, 130</i>.<br><span><b>Étym</b>. ῥόδον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ροδος - Ῥόδος</font>\n<br><br>vient probablement de rhodon (une rose)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>"};
